#!/usr/bin/env bash
# OFF-only display/history update. No trading source, setting or order mutation.
(
set -Eeuo pipefail
umask 077
cd /root/harun-ai-trading-office
HARUN_PNL_STAGE=PREFLIGHT
HARUN_PNL_RESTORE_READY=0
HARUN_PNL_WORKER_STOPPED=0
[ "$(id -u)" = 0 ] || { printf '%s\n' ROOT_REQUIRED; exit 1; }
HARUN_PNL_CONFIG="$(docker inspect --format '{{index .Config.Labels "com.docker.compose.project.config_files"}}' harun-office-worker-1)"
[ "$HARUN_PNL_CONFIG" = /root/harun-ai-trading-office/compose.yaml ] || { printf '%s\n' COMPOSE_CONFIGURATION_CHANGED; exit 1; }
HARUN_PNL_BACKUP="$(mktemp -d /root/harun-pnl-calendar.XXXXXX)"
HARUN_PNL_BUILD_MAP="$(python3 -I -B -S - <<'HARUN_PNL_BUILD_MAP'
import hashlib,json,stat
from pathlib import Path
values={}
for name in ('Dockerfile','.dockerignore','compose.yaml','worker/requirements.txt'):
    p=Path(name);info=p.lstat()
    assert stat.S_ISREG(info.st_mode) and info.st_nlink==1, 'BUILD_CONFIGURATION_INVALID'
    values[name]=hashlib.sha256(p.read_bytes()).hexdigest()
print(json.dumps(values,sort_keys=True))
HARUN_PNL_BUILD_MAP
)"
harun_pnl_check_build() {
  python3 -I -B -S - "$HARUN_PNL_BUILD_MAP" <<'HARUN_PNL_BUILD_CHECK'
import hashlib,json,stat,sys
from pathlib import Path
for name,sha in json.loads(sys.argv[1]).items():
    p=Path(name);info=p.lstat()
    assert stat.S_ISREG(info.st_mode) and info.st_nlink==1 and hashlib.sha256(p.read_bytes()).hexdigest()==sha, 'BUILD_CONFIGURATION_CHANGED'
HARUN_PNL_BUILD_CHECK
}
cat > "$HARUN_PNL_BACKUP/install.py" <<'HARUN_PNL_HELPER'
