TARGET_CONTENTS = {'worker/pnl_calendar.py': '"""Private, incremental USD-M fill history and reconstructed closed-position PNL.\n\nBinance\'s public signed API exposes fills and income, not the mobile app\'s\nposition-history records. A flat-to-flat lifecycle is reconstructed from those\nfacts. Historical leverage/ROI are deliberately absent. This reader has no\norder interface and never writes the trading ledger.\n"""\nimport fcntl\nimport hashlib\nimport json\nimport os\nimport re\nimport stat\nimport tempfile\nimport time\nfrom datetime import datetime, timedelta, timezone\nfrom decimal import Decimal, localcontext, ROUND_DOWN\nfrom pathlib import Path\n\nfrom .binance_private import BinanceCheckError, CODES\nfrom .http_client import unique\n\nWIB = timezone(timedelta(hours=7))\nDAY_MS = 86_400_000\nWINDOW_MS = 7 * DAY_MS\nSTART_DATE = \'2026-10-01\'\nSTART_MS = int(datetime(2026, 10, 1, tzinfo=WIB).timestamp()) * 1000\n# A carry-in whose opening precedes this bounded bootstrap stays incomplete.\nBOOTSTRAP_MS = START_MS - WINDOW_MS\nCACHE_NAME = \'pnl-history-v1.json\'\nPAGE_SIZE = 1000\nMAX_REQUESTS = 4\nMAX_SECONDS = 15\nMAX_SYMBOLS = 100\nMAX_ROWS = 100_000\nMAX_CACHE_BYTES = 32_000_000\nSYMBOL = re.compile(r\'[A-Z0-9_]{2,26}USDT\')\nNUMBER = re.compile(r\'-?\\d+(?:\\.\\d+)?\')\n\n\ndef _ms(value):\n    if type(value) is not int or not 0 <= value < 10**16:\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    return value\n\n\ndef _number(value):\n    if not isinstance(value, str) or len(value) > 64 or not NUMBER.fullmatch(value):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    return Decimal(value)\n\n\ndef _iso(value):\n    return datetime.fromtimestamp(value / 1000, timezone.utc).isoformat(timespec=\'milliseconds\').replace(\'+00:00\', \'Z\')\n\n\ndef _date(value):\n    return datetime.fromtimestamp(value / 1000, WIB).date().isoformat()\n\n\ndef _fixed(value):\n    result = format(value, \'f\')\n    if len(result) > 64:\n        raise ValueError(\'PNL_VALUE_LIMIT\')\n    return result\n\n\ndef _average(value):\n    result = _fixed(value.quantize(Decimal(\'0.0000000000000001\')))\n    return result.rstrip(\'0\').rstrip(\'.\') if \'.\' in result else result\n\n\ndef _integer(value):\n    if type(value) is not int or not 0 <= value < 2**63:\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    return value\n\n\ndef _fill(raw):\n    if not isinstance(raw, dict) or not isinstance(raw.get(\'symbol\'), str) or not SYMBOL.fullmatch(raw[\'symbol\']):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    if raw.get(\'side\') not in (\'BUY\', \'SELL\') or raw.get(\'positionSide\') not in (\'BOTH\', \'LONG\', \'SHORT\'):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    if not isinstance(raw.get(\'commissionAsset\'), str) or not re.fullmatch(r\'[A-Z0-9]{1,16}\', raw[\'commissionAsset\']):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    for field in (\'qty\', \'price\', \'realizedPnl\', \'commission\'):\n        value = _number(raw[field])\n        if field in (\'qty\', \'price\') and value <= 0:\n            raise ValueError(\'PNL_HISTORY_INVALID\')\n    return {key: raw[key] for key in (\'symbol\', \'side\', \'positionSide\', \'qty\', \'price\', \'realizedPnl\', \'commission\', \'commissionAsset\')} | {\n        \'id\': _integer(raw[\'id\']), \'orderId\': _integer(raw[\'orderId\']), \'time\': _ms(raw[\'time\'])}\n\n\ndef _income(raw):\n    if not isinstance(raw, dict):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    symbol = raw.get(\'symbol\', \'\')\n    if symbol and (not isinstance(symbol, str) or not re.fullmatch(r\'[A-Z0-9_]{3,30}\', symbol)):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    kind, asset = raw[\'incomeType\'], raw[\'asset\']\n    if not isinstance(kind, str) or not re.fullmatch(r\'[A-Z_]{1,40}\', kind):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    if not isinstance(asset, str) or not re.fullmatch(r\'[A-Z0-9]{1,16}\', asset):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    _number(raw[\'income\'])\n    return dict(symbol=symbol, incomeType=kind, asset=asset, income=raw[\'income\'],\n                time=_ms(raw[\'time\']), tranId=_integer(raw[\'tranId\']))\n\n\ndef _key(row, income=False):\n    return (row[\'incomeType\'] + \':\' + str(row[\'tranId\'])) if income else row[\'symbol\'] + \':\' + str(row[\'id\'])\n\n\ndef _merge(intervals):\n    result = []\n    for start, end in sorted(intervals):\n        _ms(start); _ms(end)\n        if start > end:\n            raise ValueError(\'PNL_CACHE_INVALID\')\n        if result and start <= result[-1][1] + 1:\n            result[-1][1] = max(result[-1][1], end)\n        else:\n            result.append([start, end])\n    return result\n\n\ndef _covers(intervals, start, end):\n    return end < start or any(a <= start and b >= end for a, b in _merge(intervals))\n\n\ndef _gap(intervals, start, end, *, latest=True):\n    """A bounded missing window, with explicit historical/tail fairness."""\n    if not latest:\n        cursor = start\n        for a, b in _merge(intervals):\n            if b < cursor:\n                continue\n            if a > cursor:\n                return [cursor, min(end, a - 1, cursor + WINDOW_MS - 1)] if cursor <= end else None\n            cursor = max(cursor, b + 1)\n        return [cursor, min(end, cursor + WINDOW_MS - 1)] if cursor <= end else None\n    for a, b in reversed(_merge(intervals)):\n        if a > end:\n            continue\n        if b < end:\n            return [max(start, b + 1, end - WINDOW_MS + 1), end]\n        end = a - 1\n    return [max(start, end - WINDOW_MS + 1), end] if end >= start else None\n\n\ndef _risk(rows):\n    if not isinstance(rows, list):\n        raise ValueError(\'PNL_POSITION_SNAPSHOT_INVALID\')\n    result = {}\n    for row in rows:\n        if not isinstance(row, dict):\n            raise ValueError(\'PNL_POSITION_SNAPSHOT_INVALID\')\n        symbol, side = row.get(\'symbol\'), row.get(\'positionSide\')\n        if not isinstance(symbol, str) or not re.fullmatch(r\'[A-Z0-9_]{3,30}\', symbol) or side not in (\'BOTH\', \'LONG\', \'SHORT\'):\n            raise ValueError(\'PNL_POSITION_SNAPSHOT_INVALID\')\n        amount = _number(row[\'positionAmt\'])\n        if side == \'LONG\' and amount < 0 or side == \'SHORT\' and amount > 0:\n            raise ValueError(\'PNL_POSITION_SNAPSHOT_INVALID\')\n        update = row.get(\'updateTime\')\n        if update is not None:\n            _ms(update)\n        key = symbol + \':\' + side\n        if key in result:\n            raise ValueError(\'PNL_POSITION_SNAPSHOT_INVALID\')\n        # Preserve zero-row updateTime as a witness of a post-cutoff close.\n        # Harmless zero-row appearance/disappearance is ignored when comparing\n        # quantities, but available race evidence must never be discarded.\n        result[key] = dict(quantity=row[\'positionAmt\'], updateTime=update)\n    return result\n\n\ndef _empty(identity):\n    return dict(version=1, identity=identity, incomes={}, fills={}, income_coverage=[],\n                trade_coverage={}, income_task=None, trade_tasks={}, blocked={}, anchors={}, turn=0, next_kind=\'INCOME\',\n                income_mode=\'TAIL\', trade_mode={})\n\n\ndef _validate(state, identity):\n    expected = set(_empty(identity))\n    if not isinstance(state, dict) or set(state) != expected or state[\'version\'] != 1:\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if not isinstance(state[\'identity\'], str) or not re.fullmatch(r\'[0-9a-f]{64}\', state[\'identity\']):\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if state[\'identity\'] != identity:\n        return _empty(identity)\n    if type(state[\'turn\']) is not int or state[\'turn\'] < 0:\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if state[\'next_kind\'] not in (\'INCOME\', \'TRADES\'):\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if state[\'income_mode\'] not in (\'TAIL\', \'BACKFILL\'):\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if any(not isinstance(state[k], dict) for k in (\'incomes\', \'fills\', \'trade_coverage\', \'trade_tasks\', \'blocked\', \'anchors\', \'trade_mode\')):\n        raise ValueError(\'PNL_CACHE_INVALID\')\n    if len(state[\'incomes\']) + len(state[\'fills\']) > MAX_ROWS:\n        raise ValueError(\'PNL_CACHE_LIMIT\')\n    for name, parser, income in ((\'incomes\', _income, True), (\'fills\', _fill, False)):\n        for key, value in state[name].items():\n            if parser(value) != value or _key(value, income) != key:\n                raise ValueError(\'PNL_CACHE_INVALID\')\n    state[\'income_coverage\'] = _merge(state[\'income_coverage\'])\n    for name in (\'trade_coverage\', \'trade_tasks\', \'blocked\'):\n        if len(state[name]) > MAX_SYMBOLS:\n            raise ValueError(\'PNL_CACHE_LIMIT\')\n        for symbol, intervals in state[name].items():\n            if not SYMBOL.fullmatch(symbol) or not isinstance(intervals, list):\n                raise ValueError(\'PNL_CACHE_INVALID\')\n            checked = _merge(intervals)\n            if name != \'trade_tasks\':\n                state[name][symbol] = checked\n            elif any(end - start >= WINDOW_MS for start, end in intervals):\n                raise ValueError(\'PNL_CACHE_INVALID\')\n    task = state[\'income_task\']\n    if task is not None:\n        if not isinstance(task, dict) or set(task) != {\'start\', \'end\', \'page\', \'seen_keys\'}:\n            raise ValueError(\'PNL_CACHE_INVALID\')\n        _ms(task[\'start\']); _ms(task[\'end\'])\n        if not task[\'start\'] <= task[\'end\'] < task[\'start\'] + WINDOW_MS or type(task[\'page\']) is not int or not 1 <= task[\'page\'] <= 100:\n            raise ValueError(\'PNL_CACHE_INVALID\')\n        if not isinstance(task[\'seen_keys\'], list) or len(task[\'seen_keys\']) > MAX_ROWS or len(set(task[\'seen_keys\'])) != len(task[\'seen_keys\']) or any(not isinstance(k, str) for k in task[\'seen_keys\']):\n            raise ValueError(\'PNL_CACHE_INVALID\')\n    for symbol, mode in state[\'trade_mode\'].items():\n        if not SYMBOL.fullmatch(symbol) or mode not in (\'TAIL\', \'BACKFILL\'):\n            raise ValueError(\'PNL_CACHE_INVALID\')\n    for symbol, anchor in state[\'anchors\'].items():\n        if not SYMBOL.fullmatch(symbol) or not isinstance(anchor, dict) or set(anchor) != {\'end\', \'quantities\'}:\n            raise ValueError(\'PNL_CACHE_INVALID\')\n        _ms(anchor[\'end\'])\n        if not isinstance(anchor[\'quantities\'], dict) or set(anchor[\'quantities\']) - {\'BOTH\', \'LONG\', \'SHORT\'}:\n            raise ValueError(\'PNL_CACHE_INVALID\')\n        for side, quantity in anchor[\'quantities\'].items():\n            amount = _number(quantity)\n            if side == \'LONG\' and amount < 0 or side == \'SHORT\' and amount > 0:\n                raise ValueError(\'PNL_CACHE_INVALID\')\n    return state\n\n\nclass HistoryCache:\n    """One private atomic file, credential-scoped, separate from ledger.sqlite3."""\n    def __init__(self, directory, identity):\n        self.directory, self.identity = Path(directory), identity\n        self.fd = self.lock = None\n\n    def __enter__(self):\n        try:\n            self.fd = os.open(self.directory, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)\n            info = os.fstat(self.fd)\n            if info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o700:\n                raise ValueError(\'PNL_CACHE_NOT_PRIVATE\')\n            self.lock = os.open(\'pnl-history.lock\', os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600, dir_fd=self.fd)\n            info = os.fstat(self.lock)\n            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o600:\n                raise ValueError(\'PNL_CACHE_NOT_PRIVATE\')\n            try:\n                fcntl.flock(self.lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n            except BlockingIOError:\n                raise ValueError(\'PNL_REFRESH_BUSY\') from None\n            return self\n        except Exception:\n            self.__exit__(None, None, None)\n            raise\n\n    def __exit__(self, *unused):\n        for fd in (self.lock, self.fd):\n            if fd is not None:\n                os.close(fd)\n        self.fd = self.lock = None\n\n    def load(self):\n        try:\n            fd = os.open(CACHE_NAME, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=self.fd)\n        except FileNotFoundError:\n            return _empty(self.identity)\n        with os.fdopen(fd, \'rb\') as source:\n            info = os.fstat(source.fileno())\n            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid() or stat.S_IMODE(info.st_mode) != 0o600:\n                raise ValueError(\'PNL_CACHE_NOT_PRIVATE\')\n            if info.st_size > MAX_CACHE_BYTES:\n                raise ValueError(\'PNL_CACHE_LIMIT\')\n            raw = source.read(MAX_CACHE_BYTES + 1)\n            if len(raw) > MAX_CACHE_BYTES:\n                raise ValueError(\'PNL_CACHE_LIMIT\')\n            try:\n                state = json.loads(raw, object_pairs_hook=unique)\n            except Exception:\n                raise ValueError(\'PNL_CACHE_INVALID\') from None\n        return _validate(state, self.identity)\n\n    def save(self, state):\n        _validate(state, self.identity)\n        raw = json.dumps(state, sort_keys=True, separators=(\',\', \':\')).encode()\n        if len(raw) > MAX_CACHE_BYTES:\n            raise ValueError(\'PNL_CACHE_LIMIT\')\n        fd, name = tempfile.mkstemp(prefix=\'.pnl-history-\', dir=self.directory)\n        try:\n            with os.fdopen(fd, \'wb\') as output:\n                output.write(raw); output.flush(); os.fsync(output.fileno())\n            os.replace(name, self.directory / CACHE_NAME)\n            os.fsync(self.fd)\n        finally:\n            try:\n                os.unlink(name)\n            except FileNotFoundError:\n                pass\n\n\ndef _put(state, name, rows, parser, start, end, symbol=None):\n    parsed = [parser(row) for row in rows]\n    if any(not start <= row[\'time\'] <= end or symbol is not None and row[\'symbol\'] != symbol for row in parsed):\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    incoming = {}\n    for row in parsed:\n        key = _key(row, name == \'incomes\')\n        if key in incoming or key in state[name] and state[name][key] != row:\n            raise ValueError(\'PNL_HISTORY_CONFLICT\')\n        incoming[key] = row\n    if len(state[\'incomes\']) + len(state[\'fills\']) + len(set(incoming) - set(state[name])) > MAX_ROWS:\n        raise ValueError(\'PNL_CACHE_LIMIT\')\n    state[name].update(incoming)\n    return list(incoming)\n\n\ndef _read(client, path, **options):\n    try:\n        return client.signed_get(path, **options)\n    except BinanceCheckError as error:\n        if str(error) != \'BINANCE_CLOCK_ERROR\':\n            raise\n    client.sync_time()\n    return client.signed_get(path, **options)\n\n\ndef _page(rows):\n    if not isinstance(rows, list) or len(rows) > PAGE_SIZE:\n        raise ValueError(\'PNL_HISTORY_INVALID\')\n    return rows\n\n\ndef _update(client, state, before, end, *, max_requests, budget_seconds):\n    deadline = time.monotonic() + budget_seconds\n    reasons = []\n    used = 0\n    # Official REST history is retained for three months. Previously cached\n    # facts survive; uncached older time remains unknown, never an empty day.\n    lower = max(BOOTSTRAP_MS, end - 90 * DAY_MS + 1)\n    if lower > BOOTSTRAP_MS and not _covers(state[\'income_coverage\'], BOOTSTRAP_MS, lower - 1):\n        reasons.append(\'HISTORY_RETENTION_LIMIT\')\n    if end < START_MS:\n        return reasons\n    if state[\'income_task\'] is None:\n        gap = _gap(state[\'income_coverage\'], lower, end, latest=state[\'income_mode\'] == \'TAIL\')\n        if gap is None:\n            gap = [max(lower, end - 2 * DAY_MS), end]\n        state[\'income_task\'] = dict(start=gap[0], end=gap[1], page=1, seen_keys=[])\n    task = state[\'income_task\']\n    if task[\'start\'] < lower:\n        state[\'income_task\'] = None\n        reasons.append(\'HISTORY_RETENTION_LIMIT\')\n    elif used < max_requests and time.monotonic() < deadline and (max_requests > 1 or state[\'next_kind\'] == \'INCOME\' or\n            not (any(SYMBOL.fullmatch(row[\'symbol\']) for row in state[\'incomes\'].values()) or\n                 any(_number(value[\'quantity\']) != 0 for value in before.values()))):\n        used += 1\n        state[\'next_kind\'] = \'TRADES\'\n        try:\n            rows = _page(_read(client, \'/fapi/v1/income\', start_time=task[\'start\'], end_time=task[\'end\'], limit=PAGE_SIZE, page=task[\'page\']))\n            keys = _put(state, \'incomes\', rows, _income, task[\'start\'], task[\'end\'])\n            if set(keys) & set(task[\'seen_keys\']):\n                task.update(page=1, seen_keys=[])\n                raise ValueError(\'PNL_HISTORY_PAGINATION_STALLED\')\n            task[\'seen_keys\'].extend(keys)\n            if len(rows) < PAGE_SIZE:\n                state[\'income_coverage\'] = _merge(state[\'income_coverage\'] + [[task[\'start\'], task[\'end\']]])\n                state[\'income_task\'] = None\n                state[\'income_mode\'] = \'BACKFILL\' if state[\'income_mode\'] == \'TAIL\' else \'TAIL\'\n            elif task[\'page\'] >= 100:\n                reasons.append(\'INCOME_PAGE_LIMIT\')\n            else:\n                task.update(page=task[\'page\'] + 1)\n        except Exception as error:\n            reasons.append(_reason(error))\n    symbols = sorted({row[\'symbol\'] for row in state[\'incomes\'].values() if SYMBOL.fullmatch(row[\'symbol\'])} |\n                     {key.rsplit(\':\', 1)[0] for key, value in before.items() if _number(value[\'quantity\']) != 0 and SYMBOL.fullmatch(key.rsplit(\':\', 1)[0])})\n    if len(symbols) > MAX_SYMBOLS:\n        reasons.append(\'HISTORY_SYMBOL_LIMIT\')\n    symbols = symbols[:MAX_SYMBOLS]\n    if symbols:\n        offset = state[\'turn\'] % len(symbols)\n        ordered = symbols[offset:] + symbols[:offset]\n        for symbol in ordered:\n            if used >= max_requests or time.monotonic() >= deadline:\n                break\n            coverage = state[\'trade_coverage\'].get(symbol, [])\n            tasks = state[\'trade_tasks\'].setdefault(symbol, [])\n            if not tasks:\n                gap = _gap(coverage + state[\'blocked\'].get(symbol, []), lower, end,\n                           latest=state[\'trade_mode\'].get(symbol, \'TAIL\') == \'TAIL\')\n                if gap is None:\n                    gap = [max(lower, end - 2 * DAY_MS), end]\n                tasks.append(gap)\n            start, finish = tasks[0]\n            if start < lower:\n                tasks.pop(0); reasons.append(\'HISTORY_RETENTION_LIMIT\'); continue\n            used += 1\n            state[\'next_kind\'] = \'INCOME\'\n            try:\n                rows = _page(_read(client, \'/fapi/v1/userTrades\', symbol=symbol, start_time=start, end_time=finish, limit=PAGE_SIZE))\n                _put(state, \'fills\', rows, _fill, start, finish, symbol)\n                tasks.pop(0)\n                if len(rows) < PAGE_SIZE:\n                    state[\'trade_coverage\'][symbol] = _merge(coverage + [[start, finish]])\n                elif start < finish:\n                    # Disjoint halves cover every same-ms boundary. Never drop\n                    # all remaining fills at the timestamp of the oldest row.\n                    middle = (start + finish) // 2\n                    tasks[0:0] = [[middle + 1, finish], [start, middle]]\n                else:\n                    state[\'blocked\'][symbol] = _merge(state[\'blocked\'].get(symbol, []) + [[start, finish]])\n                    reasons.append(\'DENSE_TRADE_TIMESTAMP_UNPROVEN\')\n                if not tasks:\n                    state[\'trade_mode\'][symbol] = \'BACKFILL\' if state[\'trade_mode\'].get(symbol, \'TAIL\') == \'TAIL\' else \'TAIL\'\n            except Exception as error:\n                reasons.append(_reason(error))\n            state[\'turn\'] += 1\n    if any(state[\'blocked\'].values()):\n        reasons.append(\'DENSE_TRADE_TIMESTAMP_UNPROVEN\')\n    if time.monotonic() >= deadline:\n        reasons.append(\'HISTORY_TIME_BUDGET\')\n        return reasons\n    after = _risk(_read(client, \'/fapi/v3/positionRisk\'))\n    for symbol in symbols:\n        old = {key: value for key, value in before.items() if key.startswith(symbol + \':\') and _number(value[\'quantity\']) != 0}\n        new = {key: value for key, value in after.items() if key.startswith(symbol + \':\') and _number(value[\'quantity\']) != 0}\n        witnesses = [value for key, value in after.items() if key.startswith(symbol + \':\')]\n        if old != new or any(value[\'updateTime\'] is not None and value[\'updateTime\'] > end for value in witnesses):\n            reasons.append(\'POSITION_SNAPSHOT_CHANGED\')\n            continue\n        if any(a <= end <= b for a, b in state[\'trade_coverage\'].get(symbol, [])):\n            state[\'anchors\'][symbol] = dict(end=end, quantities={key.rsplit(\':\', 1)[1]: value[\'quantity\'] for key, value in old.items()})\n    return reasons\n\n\ndef _new_group(symbol, position_side, amount, closed_at=None, closing_id=None):\n    return dict(symbol=symbol, position_side=position_side, side=\'LONG\' if amount > 0 else \'SHORT\',\n                opened=None, closed=closed_at, closing_id=closing_id, entry_qty=Decimal(0), entry_value=Decimal(0),\n                exit_qty=Decimal(0), exit_value=Decimal(0), realized=Decimal(0), commission=Decimal(0),\n                fee_assets=set(), opening_proven=False, funding=Decimal(0), insurance=Decimal(0), reasons=[])\n\n\ndef _component(group, row, quantity, *, opening):\n    if quantity <= 0:\n        return\n    total, whole = _number(row[\'commission\']), _number(row[\'qty\'])\n    if quantity == whole:\n        cost = total\n    else:\n        # A repeating fractional allocation cannot be serialized as hundreds of\n        # digits. Round the closing share toward zero at at least 16 decimal\n        # places, then assign its exact remainder to the opening share. The two\n        # lifecycles retain the whole original commission, including rebates.\n        closing = whole - quantity if opening else quantity\n        places = max(16, -total.as_tuple().exponent)\n        closing_cost = (total * closing / whole).quantize(Decimal(1).scaleb(-places), rounding=ROUND_DOWN).normalize()\n        cost = total - closing_cost if opening else closing_cost\n    if row[\'commissionAsset\'] == \'USDT\':\n        group[\'commission\'] += cost\n    elif cost != 0:\n        group[\'fee_assets\'].add(row[\'commissionAsset\'])\n    name = \'entry\' if opening else \'exit\'\n    group[name + \'_qty\'] += quantity\n    group[name + \'_value\'] += quantity * _number(row[\'price\'])\n    if not opening:\n        group[\'realized\'] += _number(row[\'realizedPnl\'])\n\n\ndef _groups(state, issues=None):\n    """Reverse replay from independently verified ending quantities.\n\n    Direction follows BUY/SELL and quantity, never the sign of realized PNL.\n    A reversal splits its commission pro rata; all realized PNL belongs to its\n    closing portion. Full contiguous coverage is necessary to cross a boundary.\n    """\n    groups = []\n    for symbol, anchor in sorted(state[\'anchors\'].items()):\n        end = anchor[\'end\']\n        intervals = [pair for pair in _merge(state[\'trade_coverage\'].get(symbol, [])) if pair[0] <= end <= pair[1]]\n        if not intervals:\n            continue\n        start = intervals[0][0]\n        rows = sorted((row for row in state[\'fills\'].values() if row[\'symbol\'] == symbol and start <= row[\'time\'] <= end),\n                      key=lambda row: (row[\'time\'], row[\'id\']), reverse=True)\n        quantities = {side: _number(value) for side, value in anchor[\'quantities\'].items()}\n        current = {side: _new_group(symbol, side, amount) for side, amount in quantities.items() if amount != 0}\n        symbol_groups = []\n        try:\n            for row in rows:\n                side = row[\'positionSide\']; delta = _number(row[\'qty\']) * (1 if row[\'side\'] == \'BUY\' else -1)\n                q1 = quantities.get(side, Decimal(0)); q0 = q1 - delta\n                if side == \'LONG\' and q0 < 0 or side == \'SHORT\' and q0 > 0:\n                    raise ValueError(\'POSITION_FILL_QUANTITY_MISMATCH\')\n                closing = min(abs(q0), abs(delta)) if q0 * delta < 0 else Decimal(0)\n                opening = abs(delta) - closing\n                if closing == 0 and _number(row[\'realizedPnl\']) != 0:\n                    raise ValueError(\'POSITION_FILL_QUANTITY_MISMATCH\')\n                if opening:\n                    group = current.setdefault(side, _new_group(symbol, side, q1))\n                    _component(group, row, opening, opening=True)\n                    if q0 == 0 or q0 * q1 < 0:\n                        group.update(opened=row[\'time\'], opening_proven=True)\n                        symbol_groups.append(group); current.pop(side)\n                if closing:\n                    group = current.setdefault(side, _new_group(symbol, side, q0, row[\'time\'], row[\'id\']))\n                    _component(group, row, closing, opening=False)\n                quantities[side] = q0\n            for group in current.values():\n                group[\'reasons\'].append(\'OPENING_BEFORE_HISTORY_WINDOW\')\n                symbol_groups.append(group)\n            for group in symbol_groups:\n                group.update(history_start=start, history_end=end)\n            groups.extend(symbol_groups)\n        except ValueError:\n            # A bad anchor, history gap or inconsistent exchange response cannot\n            # create a fictional flat boundary or a closed-position PNL.\n            if issues is not None:\n                issues.append(\'POSITION_FILL_QUANTITY_MISMATCH\')\n            continue\n    return groups\n\n\ndef _positions(state, end, issues=None):\n    groups = _groups(state, issues)\n    for group in groups:\n        finish = group[\'closed\'] if group[\'closed\'] is not None else group[\'history_end\']\n        if group[\'opened\'] is None or not _covers(state[\'income_coverage\'], group[\'opened\'], finish):\n            group[\'reasons\'].append(\'POSITION_INCOME_HISTORY_INCOMPLETE\')\n        if group[\'fee_assets\']:\n            group[\'reasons\'].append(\'NON_USDT_COMMISSION\')\n    for row in state[\'incomes\'].values():\n        if row[\'incomeType\'] not in (\'FUNDING_FEE\', \'INSURANCE_CLEAR\'):\n            continue\n        # Income carries symbol, but no historical position side. Attribute only\n        # if exactly one lifecycle spans the event, away from a reversal boundary.\n        matches = [group for group in groups if group[\'symbol\'] == row[\'symbol\'] and\n                   (group[\'opened\'] if group[\'opened\'] is not None else group[\'history_start\']) <= row[\'time\'] <=\n                   (group[\'closed\'] if group[\'closed\'] is not None else group[\'history_end\'])]\n        if not matches:\n            for group in groups:\n                if group[\'symbol\'] == row[\'symbol\'] and group[\'closed\'] is not None:\n                    group[\'reasons\'].append(\'POSITION_INCOME_ATTRIBUTION_UNKNOWN\')\n            continue\n        boundary = any(row[\'time\'] in (group[\'opened\'], group[\'closed\']) for group in matches)\n        if len(matches) != 1 or boundary:\n            for group in matches:\n                group[\'reasons\'].append(\'POSITION_INCOME_ATTRIBUTION_UNKNOWN\')\n        elif row[\'asset\'] != \'USDT\':\n            matches[0][\'reasons\'].append(\'NON_USDT_POSITION_INCOME\')\n        else:\n            name = \'funding\' if row[\'incomeType\'] == \'FUNDING_FEE\' else \'insurance\'\n            matches[0][name] += _number(row[\'income\'])\n    positions = []\n    for group in groups:\n        if group[\'closed\'] is None or not START_MS <= group[\'closed\'] <= end or group[\'exit_qty\'] <= 0:\n            continue\n        complete = group[\'opening_proven\'] and not group[\'reasons\']\n        fee_net = group[\'realized\'] - group[\'commission\']\n        known = fee_net + group[\'funding\'] + group[\'insurance\']\n        identity = \'{}:{}:{}:{}\'.format(group[\'symbol\'], group[\'position_side\'], group[\'closed\'], group[\'closing_id\'])\n        positions.append(dict(id=hashlib.sha256(identity.encode()).hexdigest()[:24], symbol=group[\'symbol\'], side=group[\'side\'],\n            position_side=group[\'position_side\'], status=\'CLOSED\', opened_at=_iso(group[\'opened\']) if group[\'opened\'] is not None else None,\n            closed_at=_iso(group[\'closed\']), close_date=_date(group[\'closed\']), closed_quantity=_fixed(group[\'exit_qty\']),\n            entry_price=_average(group[\'entry_value\'] / group[\'entry_qty\']) if group[\'opening_proven\'] and group[\'entry_qty\'] else None,\n            exit_price=_average(group[\'exit_value\'] / group[\'exit_qty\']), realized_pnl_usdt=_fixed(group[\'realized\']),\n            commission_usdt=_fixed(group[\'commission\']) if not group[\'fee_assets\'] else None,\n            funding_usdt=_fixed(group[\'funding\']) if complete else None, insurance_usdt=_fixed(group[\'insurance\']) if complete else None,\n            pnl_usdt=_fixed(known) if complete else None, known_pnl_usdt=_fixed(known), complete=complete,\n            calculation_method=\'REALIZED_MINUS_FEES_PLUS_FUNDING_AND_INSURANCE\' if complete else \'KNOWN_COMPONENTS_PARTIAL\',\n            incomplete_reasons=list(dict.fromkeys(group[\'reasons\'])), excluded_commission_assets=sorted(group[\'fee_assets\'])))\n    return sorted(positions, key=lambda row: (row[\'closed_at\'], row[\'id\']), reverse=True)\n\n\ndef unavailable(reason=\'HISTORY_LOADING\', end_ms=None):\n    end_ms = _ms(end_ms) if end_ms is not None else int(time.time() * 1000)\n    return dict(source=\'BINANCE_FUTURES\', kind=\'CLOSED_POSITIONS_FROM_FILLS\', status=\'UNAVAILABLE\', checked_at=None,\n                timezone=\'Asia/Jakarta\', start_date=START_DATE, end_date=max(START_DATE, _date(end_ms)), complete=False,\n                days=[], positions=[], funding_usdt=None, insurance_usdt=None, incomplete_reasons=[reason])\n\n\ndef calendar(state, end, reasons=()):\n    with localcontext() as precision:\n        precision.prec = 256\n        issues = []\n        positions = _positions(state, end, issues)\n        days = []\n        date = datetime(2026, 10, 1, tzinfo=WIB)\n        last = datetime.fromtimestamp(end / 1000, WIB).date()\n        for unused in range(36_600):\n            if date.date() > last:\n                break\n            label = date.date().isoformat()\n            rows = [row for row in positions if row[\'close_date\'] == label]\n            subtotal = sum((_number(row[\'known_pnl_usdt\']) for row in rows), Decimal(0))\n            days.append(dict(date=label, pnl_usdt=None,\n                             known_pnl_usdt=_fixed(subtotal), closed_positions=len(rows), complete=False))\n            date += timedelta(days=1)\n        incomplete = list(reasons) + issues\n        if not _covers(state[\'income_coverage\'], START_MS, end):\n            incomplete.append(\'HISTORY_LOADING\')\n        symbols = {row[\'symbol\'] for row in state[\'incomes\'].values() if SYMBOL.fullmatch(row[\'symbol\'])}\n        if any(not _covers(state[\'trade_coverage\'].get(symbol, []), START_MS, end) for symbol in symbols):\n            incomplete.append(\'HISTORY_LOADING\')\n        incomplete.extend(reason for row in positions for reason in row[\'incomplete_reasons\'])\n        incomplete.append(\'SYMBOL_DISCOVERY_NOT_EXHAUSTIVE\')\n        totals = {\'FUNDING_FEE\': Decimal(0), \'INSURANCE_CLEAR\': Decimal(0)}\n        income_complete = _covers(state[\'income_coverage\'], START_MS, end)\n        for row in state[\'incomes\'].values():\n            if START_MS <= row[\'time\'] <= end and row[\'incomeType\'] in totals:\n                if row[\'asset\'] == \'USDT\':\n                    totals[row[\'incomeType\']] += _number(row[\'income\'])\n                else:\n                    incomplete.append(\'NON_USDT_POSITION_INCOME\'); income_complete = False\n        return dict(source=\'BINANCE_FUTURES\', kind=\'CLOSED_POSITIONS_FROM_FILLS\', status=\'PARTIAL\' if state[\'incomes\'] or state[\'fills\'] else \'UNAVAILABLE\',\n            checked_at=_iso(end), timezone=\'Asia/Jakarta\', start_date=START_DATE, end_date=max(START_DATE, _date(end)), complete=False,\n            days=days, positions=positions, funding_usdt=_fixed(totals[\'FUNDING_FEE\']) if income_complete else None,\n            insurance_usdt=_fixed(totals[\'INSURANCE_CLEAR\']) if income_complete else None,\n            incomplete_reasons=list(dict.fromkeys(incomplete)))\n\n\ndef _reason(error):\n    value = str(error)\n    if isinstance(error, BinanceCheckError) and value in CODES:\n        return value\n    if isinstance(error, ValueError) and re.fullmatch(r\'(?:PNL|POSITION|INCOME|HISTORY|DENSE)_[A-Z_]{1,80}\', value):\n        return value\n    return \'PNL_HISTORY_UNAVAILABLE\'\n\n\ndef collect_calendar(client, directory, *, max_requests=MAX_REQUESTS, budget_seconds=MAX_SECONDS):\n    """At most four history GETs per refresh; durable backfill resumes next poll.\n\n    positionRisk is read before and after history. Changed snapshots cannot\n    advance a symbol\'s reverse-replay anchor. Last verified cached records remain\n    visible as partial. REST snapshots are not an atomic exchange transaction;\n    the calendar therefore identifies its reconstruction and limited scope.\n    """\n    state = None; end = None\n    try:\n        if type(max_requests) is not int or not 1 <= max_requests <= 8 or type(budget_seconds) not in (int, float) or not 0 < budget_seconds <= 30:\n            raise ValueError(\'PNL_HISTORY_INVALID\')\n        key = getattr(client, \'_key\', None)\n        if not isinstance(key, str) or not key:\n            raise ValueError(\'PNL_CACHE_IDENTITY_UNAVAILABLE\')\n        identity = hashlib.sha256(key.encode()).hexdigest()\n        with HistoryCache(directory, identity) as cache:\n            state = cache.load()\n            deadline = time.monotonic() + budget_seconds\n            client.sync_time()\n            end = client.server_time_ms()\n            before = _risk(_read(client, \'/fapi/v3/positionRisk\'))\n            end = client.server_time_ms()\n            if type(end) is not int:\n                raise ValueError(\'PNL_HISTORY_INVALID\')\n            remaining = deadline - time.monotonic()\n            reasons = (_update(client, state, before, end, max_requests=max_requests, budget_seconds=remaining)\n                       if remaining > 0 else [\'HISTORY_TIME_BUDGET\'])\n            cache.save(state)\n            return calendar(state, end, reasons)\n    except Exception as error:\n        reason = _reason(error)\n        if state is not None and end is not None:\n            try:\n                return calendar(state, end, [reason])\n            except Exception:\n                pass\n        return unavailable(reason, end)\n', 'worker/api_service.py': '"""Authenticated single robot pipeline and cached Binance Futures office reports."""\nimport hmac\nimport json\nimport os\nimport signal\nimport sqlite3\nimport threading\nimport time\nfrom http.server import BaseHTTPRequestHandler,ThreadingHTTPServer\nfrom urllib.parse import urlsplit\nfrom .core import Ledger,Review,validated_risk_target\nfrom .market import Market\nfrom .neuroapi import NeuroAPI\nfrom .state import directory\nfrom .robot import Coordinator\nfrom .robot_store import RobotStore\nfrom .order_gateway import OrderGateway\nfrom .binance_private import BinanceReadOnly\nfrom .binance_office import collect\nfrom .pnl_calendar import collect_calendar, unavailable as unavailable_calendar\n\nROBOT_POLL_SECONDS=45\nACCOUNT_POLL_SECONDS=15\nHISTORY_POLL_SECONDS=60\nACTOR_STALL_SECONDS=600\nACCOUNT_STALL_SECONDS=120\nSHUTDOWN_DRAIN_SECONDS=600\nSERVICE_FAILURE_CODES=frozenset((\'WORKER_STATE_INITIALIZATION_FAILED\',\n    \'WORKER_ACTOR_INITIALIZATION_FAILED\',\'WORKER_ACTOR_UNAVAILABLE\',\n    \'WORKER_ACCOUNT_READER_UNAVAILABLE\',\'ROBOT_COORDINATOR_UNAVAILABLE\'))\nACCOUNT_FAILURE_CODES=frozenset((\'ROBOT_ACCOUNT_UNAVAILABLE\',\'BINANCE_NOT_CONFIGURED\',\n    \'BINANCE_AUTH_FAILED\',\'BINANCE_IP_RESTRICTED\',\'BINANCE_PERMISSION_DENIED\',\n    \'BINANCE_CLOCK_ERROR\',\'BINANCE_ACCOUNT_UNAVAILABLE\',\'BINANCE_ENDPOINT_DENIED\'))\n\ndef validate_settings(value):\n    if not isinstance(value,dict) or not value or set(value)-{\'robot_on\',\'risk_target_usdt\'}:\n        raise Review(\'INVALID_ROBOT_SETTING\')\n    if \'robot_on\' in value and type(value[\'robot_on\']) is not bool:raise Review(\'INVALID_ROBOT_SETTING\')\n    if \'risk_target_usdt\' in value:\n        if type(value[\'risk_target_usdt\']) is not str:raise Review(\'INVALID_RISK_TARGET\')\n        validated_risk_target(value[\'risk_target_usdt\'])\n\ndef robot_snapshot(controller,result):\n    """Show a fixed error instead of a stale successful service observation."""\n    with controller.lock:\n        worker_failure=controller.worker_failure;account_failure=controller.account_failure\n    if worker_failure:\n        result[\'failure_code\']=worker_failure\n        if result.get(\'robot_on\'):result.update(bot_status=\'NEEDS_REVIEW\',wait_reason=None)\n    if account_failure:result.update(account_failure_code=account_failure,running_positions=None,\n        running_symbols=None,available_slots=None,manual_exposure=[],usdt_wallet_balance=None,\n        usdt_available_balance=None,account_checked_at=None)\n    return result\n\ndef office_snapshot(controller,result):\n    result[\'robot\']=robot_snapshot(controller,result[\'robot\'])\n    with controller.lock:\n        account_failure=controller.account_failure;worker_failure=controller.worker_failure\n    if account_failure:\n        result[\'account\'].update(status=\'UNAVAILABLE\',failure_code=account_failure,checked_at=None,\n            usdt_wallet_balance=None,usdt_available_balance=None,active_positions=None,positions=[],\n            position_mode=None,can_trade=None,multi_assets_margin=None)\n        reports=result.get(\'reports\',{})\n        reports.update(status=\'UNAVAILABLE\',checked_at=None,complete=False,pnl_today_usdt=None,\n            realized_pnl_today_usdt=None,commission_today_usdt=None,funding_today_usdt=None,trades_today=None)\n        result.get(\'position_history\',{}).update(status=\'UNAVAILABLE\',checked_at=None,items=[],complete=False)\n        result[\'pnl_calendar\']=unavailable_calendar(account_failure)\n    employees=result.get(\'employees\',[])\n    for employee in employees:\n        if employee.get(\'status\')!=\'WORKING\':continue\n        if ((worker_failure and employee.get(\'id\') in (\'market\',\'neuro\',\'risk\',\'trading\'))\n                or (account_failure and employee.get(\'id\')==\'position\')):\n            employee[\'status\']=\'IDLE\'\n    if worker_failure or account_failure:\n        working=any(employee.get(\'id\')!=\'boss\' and employee.get(\'status\')==\'WORKING\' for employee in employees)\n        for employee in employees:\n            if employee.get(\'id\')==\'boss\':employee[\'status\']=\'WORKING\' if working else \'IDLE\'\n    return result\n\nclass Controller:\n    def __init__(self,data):\n        try:self.directory=directory(data)\n        except Exception:raise RuntimeError(\'WORKER_STATE_INITIALIZATION_FAILED\') from None\n        self.lock=threading.Lock();self.state_lock=threading.Lock()\n        self.stopping=threading.Event();self.robot_wakeup=threading.Event()\n        self.busy=False;self.checked=0;self.worker_failure=None;self.account_failure=None\n        self.worker_progress=self.account_progress=time.monotonic()\n        # WAL, robot state and paid-request journal are initialized before either\n        # actor opens a competing connection. This initialization sends no request.\n        try:\n            ledger=self.open_ledger()\n            try:\n                with self.state_lock:NeuroAPI(ledger)\n            finally:ledger.db.close()\n        except Exception:raise RuntimeError(\'WORKER_STATE_INITIALIZATION_FAILED\') from None\n        self.thread=threading.Thread(target=self.loop,daemon=True)\n        self.account_thread=threading.Thread(target=self.account_loop,daemon=True)\n        self.thread.start();self.account_thread.start()\n    def open_ledger(self):\n        with self.state_lock:\n            ledger=Ledger(self.directory/\'ledger.sqlite3\')\n            try:RobotStore(ledger.db)\n            except Exception:\n                ledger.db.close();raise\n            return ledger\n    def failure(self,code,account=False):\n        if code not in SERVICE_FAILURE_CODES:code=\'WORKER_ACTOR_UNAVAILABLE\'\n        field=\'account_failure\' if account else \'worker_failure\'\n        with self.lock:\n            changed=getattr(self,field)!=code;setattr(self,field,code)\n        if changed:print(json.dumps({\'event\':\'WORKER_SERVICE_FAILURE\',\'code\':code}),flush=True)\n    def clear_failure(self,account=False):\n        with self.lock:setattr(self,\'account_failure\' if account else \'worker_failure\',None)\n    def progress(self,account=False):\n        with self.lock:\n            if account:self.account_progress=time.monotonic()\n            else:self.worker_progress=time.monotonic()\n    def healthy(self):\n        with self.lock:\n            now=time.monotonic()\n            fresh=now-self.worker_progress<ACTOR_STALL_SECONDS and now-self.account_progress<ACCOUNT_STALL_SECONDS\n        return fresh and not self.stopping.is_set() and self.thread.is_alive() and self.account_thread.is_alive()\n    def drain(self,timeout=SHUTDOWN_DRAIN_SECONDS):\n        self.stopping.set();self.robot_wakeup.set();deadline=time.monotonic()+timeout\n        for actor in (self.thread,self.account_thread):actor.join(timeout=max(0,deadline-time.monotonic()))\n    def read_state(self,office=False):\n        db=sqlite3.connect((self.directory/\'ledger.sqlite3\').as_uri()+\'?mode=ro\',uri=True,timeout=5)\n        try:\n            db.row_factory=sqlite3.Row;db.execute(\'PRAGMA query_only=ON\')\n            store=RobotStore(db,initialize=False)\n            return office_snapshot(self,store.office_snapshot()) if office else robot_snapshot(self,store.snapshot())\n        finally:db.close()\n    def robot(self,value=None):\n        if value is None:return self.read_state()\n        validate_settings(value)\n        ledger=self.open_ledger()\n        try:\n            with self.state_lock:\n                store=RobotStore(ledger.db)\n                was_on=store.settings()[\'robot_on\'];result=store.configure(value)\n                if result[\'robot_on\'] and not was_on:self.robot_wakeup.set()\n            return robot_snapshot(self,result)\n        finally:ledger.db.close()\n    def office(self):return self.read_state(office=True)\n    def account_loop(self):\n        ledger=None;last_history=float(\'-inf\')\n        try:\n            ledger=self.open_ledger()\n            with self.state_lock:store=RobotStore(ledger.db)\n            while not self.stopping.is_set():\n                self.progress(account=True)\n                try:\n                    history=time.monotonic()-last_history>=HISTORY_POLL_SECONDS\n                    try:\n                        client=BinanceReadOnly()\n                        observation=collect(client,include_history=history)\n                        if history:\n                            observation[\'pnl_calendar\']=collect_calendar(client,self.directory,max_requests=1,budget_seconds=10)\n                            if observation[\'pnl_calendar\'][\'checked_at\'] is None:\n                                observation[\'pnl_calendar\'][\'checked_at\']=observation[\'generated_at\']\n                    except Exception as error:\n                        reason=str(error)\n                        store.report_office_failure(reason if reason in ACCOUNT_FAILURE_CODES else \'BINANCE_ACCOUNT_UNAVAILABLE\')\n                    else:\n                        store.report_office(observation)\n                        if history:last_history=time.monotonic()\n                    self.clear_failure(account=True)\n                except Exception:self.failure(\'WORKER_ACCOUNT_READER_UNAVAILABLE\',account=True)\n                self.progress(account=True)\n                if self.stopping.wait(ACCOUNT_POLL_SECONDS):break\n        except Exception:self.failure(\'WORKER_ACCOUNT_READER_UNAVAILABLE\',account=True)\n        finally:\n            if ledger is not None:ledger.db.close()\n    def loop(self):\n        ledger=None;initialized=False;last_tick=float(\'-inf\')\n        try:\n            ledger=self.open_ledger()\n            with self.state_lock:\n                client=NeuroAPI(ledger)\n                market=Market(int(os.getenv(\'OFFICE_CANDLE_LOOKBACK\',\'100\')),int(os.getenv(\'OFFICE_MARKET_MAX_AGE\',\'180\')))\n                coordinator=Coordinator(ledger,client,market,BinanceReadOnly,stopping=self.stopping)\n            initialized=True\n            while not self.stopping.is_set():\n                self.progress()\n                if self.robot_wakeup.is_set() or time.monotonic()-last_tick>=ROBOT_POLL_SECONDS:\n                    self.robot_wakeup.clear();last_tick=time.monotonic()\n                    with self.lock:self.busy=True\n                    try:coordinator.tick();self.clear_failure()\n                    except Exception:self.failure(\'ROBOT_COORDINATOR_UNAVAILABLE\')\n                    finally:\n                        with self.lock:self.checked=time.time();self.busy=False\n                        self.progress()\n                self.robot_wakeup.wait(1)\n        except Exception:self.failure(\'WORKER_ACTOR_UNAVAILABLE\' if initialized else \'WORKER_ACTOR_INITIALIZATION_FAILED\')\n        finally:\n            if ledger is not None:ledger.db.close()\n\ndef handler(controller,read_token,control_token,origin):\n    u=urlsplit(origin)\n    if u.scheme!=\'https\' or not u.netloc or u.path not in (\'\',\'/\') or u.query or u.fragment or u.username:raise ValueError(\'INVALID_ORIGIN\')\n    if min(len(read_token),len(control_token))<32 or hmac.compare_digest(read_token,control_token):raise ValueError(\'INVALID_WORKER_AUTH\')\n    class Handler(BaseHTTPRequestHandler):\n        def log_message(self,*args):pass\n        def reply(self,code,data):\n            raw=json.dumps(data).encode();self.send_response(code)\n            self.send_header(\'Content-Type\',\'application/json\');self.send_header(\'Cache-Control\',\'no-store\')\n            if self.headers.get(\'Origin\')==origin:\n                self.send_header(\'Access-Control-Allow-Origin\',origin);self.send_header(\'Vary\',\'Origin\')\n            self.send_header(\'Access-Control-Allow-Headers\',\'Authorization, Content-Type\');self.send_header(\'Access-Control-Allow-Methods\',\'GET, POST, OPTIONS\')\n            self.send_header(\'Content-Length\',str(len(raw)));self.end_headers();self.wfile.write(raw)\n        def authorized(self,control=False):\n            value=self.headers.get(\'Authorization\',\'\')\n            return hmac.compare_digest(value,\'Bearer \'+control_token) or (not control and hmac.compare_digest(value,\'Bearer \'+read_token))\n        def do_OPTIONS(self):\n            if self.path not in (\'/health\',\'/robot/status\',\'/office/status\',\'/robot/settings\'):return self.reply(404,{\'error\':\'NOT_FOUND\'})\n            self.send_response(204)\n            if self.headers.get(\'Origin\')==origin:\n                self.send_header(\'Access-Control-Allow-Origin\',origin);self.send_header(\'Vary\',\'Origin\')\n            self.send_header(\'Access-Control-Allow-Headers\',\'Authorization, Content-Type\')\n            self.send_header(\'Access-Control-Allow-Methods\',\'GET, POST, OPTIONS\');self.end_headers()\n        def do_GET(self):\n            if not self.authorized():return self.reply(403,{\'error\':\'FORBIDDEN\'})\n            if self.path==\'/health\':\n                try:\n                    gateway=OrderGateway().status();connected=gateway[\'connected\']\n                    if type(connected) is not bool:raise ValueError\n                except Exception:return self.reply(503,{\'error\':\'GATEWAY_STATUS_UNAVAILABLE\',\'mode\':\'ORDER_PIPELINE\'})\n                return self.reply(200,{\'status\':\'ONLINE\' if controller.healthy() else \'OFFLINE\',\n                    \'mode\':\'ORDER_PIPELINE\',\'gateway_connected\':connected})\n            if self.path in (\'/robot/status\',\'/office/status\'):\n                try:return self.reply(200,controller.office() if self.path==\'/office/status\' else controller.robot())\n                except Exception:return self.reply(503,{\'error\':\'WORKER_STATE_UNAVAILABLE\',\'mode\':\'ORDER_PIPELINE\'})\n            return self.reply(404,{\'error\':\'NOT_FOUND\'})\n        def do_POST(self):\n            if self.path!=\'/robot/settings\':return self.reply(404,{\'error\':\'NOT_FOUND\'})\n            if not self.authorized(True) or self.headers.get(\'Origin\')!=origin:return self.reply(403,{\'error\':\'FORBIDDEN\'})\n            try:\n                from .http_client import unique\n                length=self.headers.get(\'Content-Length\',\'\')\n                if self.headers.get(\'Transfer-Encoding\') or not length.isdigit() or not 0<int(length)<=1024 or self.headers.get(\'Content-Type\')!=\'application/json\':raise ValueError\n                self.connection.settimeout(5)\n                value=json.loads(self.rfile.read(int(length)),object_pairs_hook=unique)\n                validate_settings(value)\n                return self.reply(200,controller.robot(value))\n            except Exception:return self.reply(400,{\'error\':\'ROBOT_CONTROL_REJECTED\'})\n    return Handler\n\ndef main():\n    os.umask(0o077)\n    controller=Controller(os.getenv(\'OFFICE_DATA_DIR\',\'/data\'))\n    server=ThreadingHTTPServer((\'0.0.0.0\',8787),handler(controller,os.environ[\'OFFICE_READ_TOKEN\'],os.environ[\'OFFICE_CONTROL_TOKEN\'],os.getenv(\'OFFICE_DASHBOARD_ORIGIN\',\'https://harun5231.github.io\')))\n    stalled_actor=threading.Event()\n    def stop(*args):\n        controller.stopping.set();controller.robot_wakeup.set()\n        threading.Thread(target=server.shutdown,daemon=True).start()\n    signal.signal(signal.SIGTERM,stop);signal.signal(signal.SIGINT,stop)\n    def watchdog():\n        while not controller.stopping.wait(2):\n            if not controller.healthy():\n                with controller.lock:\n                    elapsed=time.monotonic()-controller.worker_progress\n                    actor_failed=not controller.thread.is_alive() or elapsed>=ACTOR_STALL_SECONDS\n                    if elapsed>=ACTOR_STALL_SECONDS:stalled_actor.set()\n                controller.failure(\'WORKER_ACTOR_UNAVAILABLE\' if actor_failed else \'WORKER_ACCOUNT_READER_UNAVAILABLE\',account=not actor_failed)\n                controller.stopping.set();controller.robot_wakeup.set();server.shutdown();return\n    threading.Thread(target=watchdog,daemon=True).start()\n    try:server.serve_forever()\n    finally:\n        controller.stopping.set();controller.robot_wakeup.set();server.server_close()\n        controller.drain(timeout=0 if stalled_actor.is_set() else SHUTDOWN_DRAIN_SECONDS)\nif __name__==\'__main__\':main()\n', 'worker/robot_store.py': '"""Persistent research/order journal and read-only Binance office snapshots."""\nimport json\nfrom datetime import datetime, timezone\nfrom .core import D, Review, day, now, validated_risk_target\nfrom .account_state import (empty_account, account_observation, newer_account,\n                            newer_account_json, account_order, account_timestamp, slots)\nfrom .migration import retire_previous_runtime, upgrade_cycle_namespaces\nfrom .order_gateway import OrderGateway\nfrom .robot_provenance import verify\nfrom .pnl_calendar import unavailable as unavailable_calendar\n\nACTIVE_ORDERS = (\'READY_FOR_EXECUTION\', \'EXECUTION_BLOCKED\', \'SUBMITTING\',\n                 \'ENTRY_PENDING\', \'POSITION_PROTECTED\', \'NEEDS_REVIEW\')\n\n\ndef public(value):\n    if isinstance(value, dict):\n        return {key: public(item) for key, item in value.items() if not key.startswith(\'_\')}\n    if isinstance(value, list): return [public(item) for item in value]\n    return value\n\n\ndef unavailable_office():\n    return dict(source=\'BINANCE_FUTURES\', generated_at=None,\n        account=dict(status=\'UNAVAILABLE\', checked_at=None, usdt_wallet_balance=None,\n                     usdt_available_balance=None, positions=[], active_positions=None),\n        reports=dict(status=\'UNAVAILABLE\', checked_at=None, pnl_today_usdt=None,\n                     trades_today=None, complete=False),\n        position_history=dict(status=\'UNAVAILABLE\', checked_at=None, items=[],\n                              complete=False, kind=\'BINANCE_FILLS\'),\n        pnl_calendar=unavailable_calendar())\n\n\ndef newer_section(incoming, previous):\n    checked = account_timestamp(incoming.get(\'checked_at\'))\n    prior = account_timestamp(previous.get(\'checked_at\'))\n    return checked is not None and (prior is None or checked >= prior)\n\n\nclass RobotStore:\n    def __init__(self, db, initialize=True):\n        self.db = db\n        db.create_function(\'robot_account_newer\', 2, newer_account_json)\n        if not initialize: return\n        retire_previous_runtime(db)\n        upgrade_cycle_namespaces(db)\n        db.executescript(\'\'\'\n        CREATE TABLE IF NOT EXISTS robot_settings(id INTEGER PRIMARY KEY CHECK(id=1),enabled INTEGER NOT NULL,risk TEXT NOT NULL);\n        INSERT OR IGNORE INTO robot_settings VALUES(1,0,\'5\');\n        CREATE TABLE IF NOT EXISTS robot_cycles(id TEXT PRIMARY KEY,day TEXT NOT NULL,entry_epoch INTEGER NOT NULL,state TEXT NOT NULL,data TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS robot_jobs(operation TEXT PRIMARY KEY,cycle TEXT NOT NULL,kind TEXT NOT NULL,symbol TEXT,state TEXT NOT NULL,risk_target TEXT);\n        CREATE TABLE IF NOT EXISTS robot_candidates(id TEXT PRIMARY KEY,cycle TEXT NOT NULL,symbol TEXT NOT NULL,status TEXT NOT NULL,plan TEXT,failure_code TEXT,UNIQUE(cycle,symbol));\n        CREATE TABLE IF NOT EXISTS order_intents(id TEXT PRIMARY KEY,candidate_id TEXT UNIQUE NOT NULL,symbol TEXT NOT NULL,state TEXT NOT NULL,payload TEXT NOT NULL,result TEXT,failure_code TEXT,created TEXT NOT NULL,updated TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS robot_entry_receipts(id TEXT PRIMARY KEY,symbol TEXT NOT NULL,entry_day TEXT NOT NULL,confirmed_at TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS robot_status(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS office_cache(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);\n        CREATE TABLE IF NOT EXISTS office_activity(seq INTEGER PRIMARY KEY,at TEXT NOT NULL,state TEXT NOT NULL,agent TEXT NOT NULL,message TEXT NOT NULL);\n        \'\'\')\n\n    def settings(self):\n        row = self.db.execute(\'SELECT enabled,risk FROM robot_settings WHERE id=1\').fetchone()\n        return dict(robot_on=bool(row[\'enabled\']), risk_target_usdt=format(validated_risk_target(row[\'risk\']), \'f\'))\n\n    def configure(self, value):\n        if not isinstance(value, dict) or not value or set(value) - {\'robot_on\', \'risk_target_usdt\'}:\n            raise Review(\'INVALID_ROBOT_SETTING\')\n        if \'robot_on\' in value and type(value[\'robot_on\']) is not bool:\n            raise Review(\'INVALID_ROBOT_SETTING\')\n        if \'risk_target_usdt\' in value:\n            if not isinstance(value[\'risk_target_usdt\'], str): raise Review(\'INVALID_RISK_TARGET\')\n            target = format(validated_risk_target(value[\'risk_target_usdt\']), \'f\')\n        self.db.execute(\'BEGIN IMMEDIATE\')\n        try:\n            if \'robot_on\' in value:\n                self.db.execute(\'UPDATE robot_settings SET enabled=? WHERE id=1\', (int(value[\'robot_on\']),))\n                self.event(\'ON\' if value[\'robot_on\'] else \'OFF\', \'Coordinator\', \'Pilihan robot disimpan.\')\n            if \'risk_target_usdt\' in value:\n                self.db.execute(\'UPDATE robot_settings SET risk=? WHERE id=1\', (target,))\n                self.event(\'RISK_UPDATED\', \'Risk Manager\', \'Risk per SL disimpan: \' + target + \' USDT.\')\n            self.db.execute(\'COMMIT\')\n        except BaseException: self.db.execute(\'ROLLBACK\'); raise\n        return self.snapshot()\n\n    def entries(self, today):\n        return self.db.execute(\'SELECT COUNT(*) FROM robot_entry_receipts WHERE entry_day=?\', (today,)).fetchone()[0]\n\n    def available_slots(self, running, symbols, today, *, pending_symbols=()):\n        """One capacity rule for submission, screening, and read-only Office."""\n        active=list(self.db.execute("SELECT symbol,state FROM order_intents WHERE state IN (\'ENTRY_PENDING\',\'POSITION_PROTECTED\')"))\n        pending=sum(row[\'state\']==\'ENTRY_PENDING\' for row in active)\n        # A symbol already running or present in Binance open entry orders is\n        # counted once, even when the same bot intent also reserves that symbol.\n        represented=set(symbols)\n        reserved=set(pending_symbols)|{row[\'symbol\'] for row in active}\n        unrepresented=len(reserved-represented)\n        return slots(running,self.entries(today),pending=pending,unrepresented=unrepresented)\n\n    def results(self, cycle):\n        return list(self.db.execute(\'SELECT * FROM robot_candidates WHERE cycle=?\', (cycle,)))\n\n    def verified_plan(self, row):\n        try:\n            plan = json.loads(row[\'plan\'])\n            if row[\'symbol\'] != plan[\'symbol\'] or row[\'cycle\'] != row[\'id\'].rsplit(\':analysis-v9:\', 1)[0]: raise ValueError\n            verify(self.db, plan, row[\'id\'])\n            return plan\n        except Exception: raise Review(\'ORDER_EVIDENCE_UNVERIFIED\') from None\n\n    def event(self, state, agent, message):\n        self.db.execute(\'INSERT INTO office_activity(at,state,agent,message) VALUES(?,?,?,?)\',\n                        (now(), state, agent, message))\n\n    def snapshot(self):\n        today=day()\n        row = self.db.execute(\'SELECT data FROM robot_status WHERE id=1\').fetchone()\n        value = empty_account()\n        value.update(json.loads(row[0]) if row else dict(bot_status=\'OFF\', checked_at=None, failure_code=None, wait_reason=\'ROBOT_OFF\'))\n        value.update(self.settings(), bot_entries_today=self.entries(today), execution_gateway=OrderGateway().status())\n        running=value.get(\'running_positions\');symbols=value.get(\'running_symbols\')\n        if type(running) is int and running>=0 and isinstance(symbols,list) and not value.get(\'account_failure_code\'):\n            value[\'available_slots\']=self.available_slots(running,symbols,today,\n                pending_symbols=value.get(\'open_entry_symbols\') or ())\n        if not value[\'robot_on\']: value.update(bot_status=\'OFF\', wait_reason=\'ROBOT_OFF\')\n        row = self.db.execute(\'SELECT symbol,status,failure_code FROM robot_candidates ORDER BY rowid DESC LIMIT 1\').fetchone()\n        value[\'last_decision\'] = dict(row) if row else None\n        return public(value)\n\n    def report(self, state, account=None, reason=None, wait_reason=None):\n        observation = account_observation(account) if account else empty_account()\n        encoded = json.dumps(observation)\n        previous = self.db.execute(\'SELECT data FROM robot_status WHERE id=1\').fetchone()\n        previous = json.loads(previous[0]) if previous else {}\n        self.db.execute(\'\'\'INSERT OR REPLACE INTO robot_status\n          SELECT 1,json_set(CASE WHEN ? AND robot_account_newer(?,previous)\n            THEN json_patch(previous,?) ELSE previous END,\n            \'$.bot_status\',?,\'$.failure_code\',?,\'$.wait_reason\',?,\'$.checked_at\',?)\n          FROM (SELECT COALESCE((SELECT data FROM robot_status WHERE id=1),?) AS previous)\'\'\',\n          (bool(account), encoded, encoded, state, reason, wait_reason, now(), json.dumps(empty_account())))\n        if (previous.get(\'bot_status\'), previous.get(\'failure_code\'), previous.get(\'wait_reason\')) != (state, reason, wait_reason):\n            agent = {\'SCREENING\': \'Market Analyst\', \'ANALYZING\': \'Neurobro\',\n                     \'VALIDATING\': \'Risk Manager\', \'EXECUTING\': \'Trading Agent\',\n                     \'EXECUTION_BLOCKED\': \'Trading Agent\'}.get(state, \'Coordinator\')\n            self.event(state, agent, state + (\': \' + reason if reason else \'\'))\n        return self.snapshot()\n\n    def report_account(self, account=None, reason=None):\n        observation = account_observation(account, reason, stamp=True)\n        self.db.execute(\'BEGIN IMMEDIATE\')\n        try:\n            row = self.db.execute(\'SELECT data FROM robot_status WHERE id=1\').fetchone()\n            value = json.loads(row[0]) if row else dict(bot_status=\'OFF\', failure_code=None, wait_reason=\'ROBOT_OFF\', checked_at=None)\n            if newer_account(observation, value): value.update(observation)\n            self.db.execute(\'INSERT OR REPLACE INTO robot_status VALUES(1,?)\', (json.dumps(value),))\n            self.db.execute(\'COMMIT\')\n        except BaseException: self.db.execute(\'ROLLBACK\'); raise\n\n    def report_office(self, observation):\n        self.db.execute(\'BEGIN IMMEDIATE\')\n        try:\n            row = self.db.execute(\'SELECT data FROM office_cache WHERE id=1\').fetchone()\n            value = json.loads(row[0]) if row else unavailable_office()\n            incoming = dict(observation)\n            # History collection can finish after a later account observation.\n            if \'account\' in incoming and not newer_account(incoming[\'account\'], value[\'account\']):\n                incoming.pop(\'account\')\n            for section in (\'reports\', \'position_history\', \'pnl_calendar\'):\n                if section in incoming and not newer_section(incoming[section], value.get(section, {})):\n                    incoming.pop(section)\n            generated = account_timestamp(incoming.get(\'generated_at\'))\n            previous_generated = account_timestamp(value.get(\'generated_at\'))\n            if previous_generated and (generated is None or generated < previous_generated):\n                incoming.pop(\'generated_at\', None)\n            value.update(incoming)\n            self.db.execute(\'INSERT OR REPLACE INTO office_cache VALUES(1,?)\', (json.dumps(value),))\n            self.db.execute(\'COMMIT\')\n        except BaseException: self.db.execute(\'ROLLBACK\'); raise\n        account = value[\'account\']\n        if account.get(\'status\') != \'CONNECTED\': return\n        running = [row[\'symbol\'] for row in account[\'positions\']]\n        pending_symbols=account.get(\'open_entry_symbols\') or ()\n        summary = dict(running_positions=account[\'active_positions\'], running_symbols=running,\n            open_entry_symbols=list(pending_symbols),manual_exposure=sorted(set(running)),\n            available_slots=self.available_slots(account[\'active_positions\'],running,day(),pending_symbols=pending_symbols),\n            usdt_wallet_balance=account[\'usdt_wallet_balance\'], usdt_available_balance=account[\'usdt_available_balance\'],\n            account_checked_at=account[\'checked_at\'], **{key: account[key] for key in (\'_account_generation\', \'_account_revision\') if key in account})\n        self.report_account(summary)\n\n    def report_office_failure(self, reason):\n        self.db.execute(\'BEGIN IMMEDIATE\')\n        try:\n            row = self.db.execute(\'SELECT data FROM office_cache WHERE id=1\').fetchone()\n            value = json.loads(row[0]) if row else unavailable_office()\n            value[\'account\'] = unavailable_office()[\'account\']\n            failed_at = now()\n            completion = account_order()\n            value[\'account\'].update(checked_at=failed_at, failure_code=reason, **completion)\n            value[\'reports\'] = unavailable_office()[\'reports\']\n            # An unavailable refresh must not present cached account fills as\n            # the current account observation.\n            value[\'position_history\'] = unavailable_office()[\'position_history\']\n            value[\'pnl_calendar\'] = unavailable_calendar(reason)\n            for section in (\'reports\', \'position_history\', \'pnl_calendar\'):\n                value[section].update(checked_at=failed_at, failure_code=reason)\n            value.update(generated_at=failed_at)\n            self.db.execute(\'INSERT OR REPLACE INTO office_cache VALUES(1,?)\', (json.dumps(value),))\n            self.db.execute(\'COMMIT\')\n        except BaseException: self.db.execute(\'ROLLBACK\'); raise\n        self.report_account(dict(account_checked_at=failed_at, **completion), reason=reason)\n\n    def office_snapshot(self):\n        row = self.db.execute(\'SELECT data FROM office_cache WHERE id=1\').fetchone()\n        value = json.loads(row[0]) if row else unavailable_office()\n        value.setdefault(\'pnl_calendar\', unavailable_calendar())\n        robot = self.snapshot()\n        value.update(schema_version=2, source=\'BINANCE_FUTURES\', robot=robot)\n        value[\'activity\'] = [dict(row) for row in self.db.execute(\'SELECT at,state,agent,message FROM office_activity ORDER BY seq DESC LIMIT 100\')][::-1]\n        state = robot[\'bot_status\']\n        tasks = {\'market\': state == \'SCREENING\', \'neuro\': state == \'ANALYZING\',\n                 \'risk\': state == \'VALIDATING\', \'trading\': state == \'EXECUTING\'}\n        try:\n            checked = datetime.fromisoformat(value[\'account\'][\'checked_at\'])\n            fresh = 0 <= (datetime.now(timezone.utc) - checked).total_seconds() <= 120\n        except (ValueError, TypeError): fresh = False\n        tasks[\'position\'] = robot[\'robot_on\'] and fresh and value[\'account\'].get(\'status\') == \'CONNECTED\' and value[\'account\'].get(\'active_positions\', 0) > 0\n        names = [(\'market\', \'Market Analyst\'), (\'neuro\', \'Neurobro\'), (\'risk\', \'Risk Manager\'),\n                 (\'trading\', \'Trading Agent\'), (\'position\', \'Position Monitor\'),\n                 (\'reviewer\', \'Trade Reviewer\'), (\'report\', \'Report Manager\'), (\'boss\', \'BOSS (Kamu)\')]\n        value[\'employees\'] = [dict(id=key, name=name, status=(\'BLOCKED\' if key == \'trading\' and state == \'EXECUTION_BLOCKED\' else\n            \'WORKING\' if tasks.get(key) or key == \'boss\' and any(tasks.values()) else \'IDLE\')) for key, name in names]\n        return public(value)\n', 'index.html': '<!doctype html>\n<html lang="id">\n<head>\n<meta charset="utf-8"/>\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"/>\n<title>Harun Trading Office — 3D</title>\n<style>\n:root{--bg:#07101d;--panel:rgba(9,17,31,.88);--line:rgba(132,167,214,.24);--cyan:#56e6ff;--green:#39e68c;--muted:#9eb2ca}\n*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050a12;color:#eff6ff;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}\n#scene{position:absolute;inset:0}canvas{display:block}\n.top{position:absolute;left:16px;right:16px;top:14px;display:flex;align-items:center;gap:12px;pointer-events:none}\n.brand{display:flex;align-items:center;gap:11px;background:var(--panel);border:1px solid var(--line);padding:10px 14px;border-radius:16px;backdrop-filter:blur(14px);box-shadow:0 12px 36px #0005}\n.logo{width:40px;height:40px;border-radius:12px;background:linear-gradient(145deg,#1d89c8,#182544 60%,#111827);display:grid;place-items:center;border:1px solid #6adfff88;font-size:21px}\n.brand strong{font-size:clamp(12px,2.2vw,19px);letter-spacing:.04em}.brand small{display:block;color:var(--green);font-size:11px;margin-top:3px}\n.stats{display:flex;gap:8px;margin-left:auto}.stat{min-width:112px;background:var(--panel);border:1px solid var(--line);padding:9px 13px;border-radius:13px;backdrop-filter:blur(14px)}.stat span{display:block;color:var(--muted);font-size:10px}.stat b{display:block;font-size:17px;margin-top:3px}.positive{color:var(--green)}\n\n.panel{position:absolute;bottom:16px;background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px 16px;backdrop-filter:blur(16px);box-shadow:0 16px 40px #0006}.panel h3{margin:0 0 10px;font-size:13px;letter-spacing:.04em}.coin{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid #ffffff12}.coin:last-child{border:0}.coinicon{width:29px;height:29px;border-radius:50%;display:grid;place-items:center;background:#f3a83b;color:#172033;font-weight:900}.coin b{font-size:12px}.coin small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.tag{margin-left:auto;color:var(--green);font-size:10px;font-weight:800}.event{display:grid;grid-template-columns:42px 90px 1fr;gap:7px;padding:6px 0;font-size:10px;border-bottom:1px solid #ffffff10}.event:last-child{border:0}.event time{color:var(--muted)}.event .role{color:#dcecff}.event .msg{color:#9fb5cf;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.bottomhint{position:absolute;left:50%;bottom:16px;transform:translateX(-50%);padding:8px 13px;border-radius:99px;background:#07101dcc;border:1px solid var(--line);font-size:10px;color:#b8cbe2;white-space:nowrap;pointer-events:none}\n#loading{position:absolute;inset:0;display:grid;place-items:center;background:#050a12;z-index:5;color:#d7eaff;text-align:center}#loading span{display:block;color:var(--cyan);font-size:12px;margin-top:8px}\n@media(max-width:700px){.top{left:9px;right:9px;top:9px;gap:6px}.brand{padding:7px 9px;gap:7px}.logo{width:32px;height:32px;font-size:17px}.brand small{font-size:9px}.stats{gap:5px}.stat{min-width:0;padding:7px 8px}.stat span{font-size:8px}.stat b{font-size:12px}.stats .stat:nth-child(2){display:none}.leftnav{left:9px;top:92px;gap:6px}.nav{width:49px;padding:9px 3px;font-size:9px}.nav i{font-size:17px}.panel{bottom:9px;padding:10px;border-radius:14px}.position{left:9px;width:calc(50vw - 14px)}.activity{right:9px;width:calc(50vw - 14px)}.panel h3{font-size:10px}.coin{gap:5px;padding:6px 0}.coinicon{width:22px;height:22px;font-size:10px}.coin b{font-size:10px}.coin small{font-size:8px}.tag{font-size:8px}.event{grid-template-columns:30px 1fr;gap:3px;font-size:8px}.event .msg{grid-column:2}.event .role{display:none}.bottomhint{bottom:144px;font-size:9px;max-width:88vw;overflow:hidden;text-overflow:ellipsis}}\n\n.menu-toggle{position:absolute;left:16px;top:100px;z-index:4;border:1px solid #6b8eb9;background:rgba(8,19,36,.94);color:#eef7ff;border-radius:14px;padding:12px 15px;font-size:15px;font-weight:800;box-shadow:0 8px 24px #0007;backdrop-filter:blur(14px)}\n.menu-toggle span{font-size:12px;margin-left:5px}\n.menu-drawer{position:absolute;left:16px;top:154px;z-index:4;width:min(270px,calc(100vw - 32px));padding:10px;background:rgba(7,16,30,.96);border:1px solid var(--line);border-radius:17px;box-shadow:0 18px 44px #0009;backdrop-filter:blur(16px)}\n.menu-item{display:flex;align-items:center;gap:12px;width:100%;padding:12px;border:0;border-radius:10px;background:transparent;color:#d8e7fa;text-align:left;font:700 14px inherit}\n.menu-item.active,.menu-item:active{background:#1455a4;color:#fff}\n.drawer-note{padding:10px 8px 5px;color:var(--muted);font-size:11px;line-height:1.4}\n.info-panel{left:50%;bottom:16px;transform:translateX(-50%);width:min(620px,calc(100vw - 32px));max-height:42vh;overflow:auto;z-index:3}\n.panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px}\n.panel-head h3{margin:0 0 10px}\n.panel-close{border:1px solid var(--line);background:#17253a;color:#fff;border-radius:9px;padding:5px 9px}\n.activity-list{margin-top:12px;border-top:1px solid #ffffff20;padding-top:12px}\n.event{display:grid;grid-template-columns:48px 110px 1fr;gap:7px;padding:7px 0;font-size:11px;border-bottom:1px solid #ffffff10}\n.event:last-child{border:0}\n@media(max-width:700px){\n .top{left:9px;right:9px;top:9px;gap:6px}\n .brand{padding:7px 9px;gap:7px;max-width:48%}\n .logo{width:30px;height:30px;font-size:16px;flex-shrink:0}\n .brand strong{font-size:11px}.brand small{font-size:8px;line-height:1.2}\n .stats{gap:4px}.stat{padding:7px 6px;min-width:0;max-width:78px}.stat span{font-size:8px}.stat b{font-size:11px;white-space:nowrap}\n .stats .stat:nth-child(2){display:none}\n .menu-toggle{left:9px;top:90px;padding:10px 12px;font-size:13px}\n .menu-drawer{left:9px;top:137px;width:min(245px,calc(100vw - 18px))}\n .menu-item{padding:10px;font-size:13px}\n .info-panel{bottom:9px;width:calc(100vw - 18px);padding:11px;max-height:38vh}\n .panel h3{font-size:11px}.coin{gap:7px;padding:6px 0}.coinicon{width:24px;height:24px;font-size:10px}.coin b{font-size:10px}.coin small{font-size:9px}.tag{font-size:9px}\n .event{grid-template-columns:38px 1fr;gap:4px;font-size:9px}.event .msg{grid-column:2}.event .role{display:none}\n .bottomhint{bottom:10px;font-size:9px;max-width:75vw;overflow:hidden;text-overflow:ellipsis;left:auto;right:9px;transform:none}\n}\n\n\n/* Refined overlay, safe-area layout, and touch controls. */\n:root{--panel:rgba(17,38,48,.94);--line:rgba(186,211,217,.22);--muted:#b4c8cf;--green:#a0e0bd}\nhtml,body{background:#dce5ea}\nbutton{font-family:inherit;cursor:pointer;touch-action:manipulation}\nbutton:focus-visible{outline:3px solid #8cdbc7;outline-offset:3px}\n.top{top:max(18px,env(safe-area-inset-top));left:max(18px,env(safe-area-inset-left));right:max(18px,env(safe-area-inset-right))}\n.brand{border-radius:12px;padding:12px 16px;box-shadow:0 8px 25px #203a4720}\n.brand strong{font-size:13px;letter-spacing:.10em}.brand small{font-size:9px;letter-spacing:.06em;margin-top:5px}\n.logo{background:#264650;border:1px solid #74979f55;border-radius:10px;color:#b3e1d4}\n.stat{border-radius:12px;min-width:110px;padding:12px 14px}.stat span{font-size:9px}.stat b{font-size:16px;font-variant-numeric:tabular-nums}\n.menu-toggle{top:104px;border-radius:12px;background:var(--panel);border:1px solid var(--line);font-size:13px;min-height:44px}\n.menu-drawer{top:158px;background:var(--panel);max-height:calc(100dvh - 180px);overflow:auto}\n.menu-item{font:600 13px/1.4 Inter,system-ui,sans-serif;min-height:44px}.menu-item.active{background:#365e68}\n.info-panel{bottom:max(20px,env(safe-area-inset-bottom));max-height:46dvh;border-radius:16px;padding:18px}\n.panel-close{min-width:44px;min-height:44px}.panel-head h3{margin:0}\n.bottomhint{background:var(--panel);bottom:max(18px,env(safe-area-inset-bottom));font-size:10px;padding:10px 16px}\n.camera-reset{position:absolute;right:max(18px,env(safe-area-inset-right));bottom:max(18px,env(safe-area-inset-bottom));z-index:2;min-width:44px;min-height:44px;border-radius:12px;background:var(--panel);border:1px solid var(--line);color:#e7f3f5;padding:10px 14px;font-size:12px}\n.event .msg{white-space:normal;line-height:1.5}.coin small{line-height:1.5}\n#loading{background:#e4ebe9;color:#24424b}#loading span{color:#597880}\n@media(max-width:700px){\n .top{display:grid;grid-template-columns:1fr;gap:8px;top:max(10px,env(safe-area-inset-top));left:10px;right:10px}\n .brand{max-width:none;width:100%;padding:9px 11px;border-radius:12px}.brand strong{font-size:12px}.brand small{font-size:8px}.logo{width:31px;height:31px}\n .stats{margin:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:5px;width:100%}\n .stats .stat:nth-child(2){display:block}.stat{max-width:none;min-width:0;padding:9px 7px;border-radius:10px}.stat span{font-size:8px;white-space:nowrap}.stat b{font-size:12px;margin-top:4px}\n .menu-toggle{top:calc(max(10px,env(safe-area-inset-top)) + 122px);left:10px;padding:10px 13px}\n .menu-drawer{top:calc(max(10px,env(safe-area-inset-top)) + 174px);left:10px;width:245px;max-height:calc(100dvh - 200px - env(safe-area-inset-top))}\n .info-panel{width:calc(100% - 20px);bottom:max(10px,env(safe-area-inset-bottom));max-height:43dvh;padding:13px}\n .event{grid-template-columns:38px 1fr;font-size:10px}.event .role{display:block;color:#c6e8e0}.event .msg{grid-column:2}\n .bottomhint{left:10px;right:auto;transform:none;bottom:max(10px,env(safe-area-inset-bottom));max-width:calc(100vw - 122px);font-size:8px;padding:11px 9px}\n .camera-reset{right:10px;bottom:max(10px,env(safe-area-inset-bottom));font-size:10px;padding:10px}\n}\n@media(max-height:500px) and (orientation:landscape){\n .top{display:flex;gap:7px}.brand{max-width:35%;padding:7px}.brand strong{font-size:9px}.brand small{font-size:7px}.stats{display:flex;margin-left:auto;width:auto}.stat{padding:7px;min-width:72px}.stat b{font-size:11px}\n .menu-toggle{top:80px}.menu-drawer{top:130px;max-height:calc(100dvh - 145px)}.info-panel{max-height:60dvh;max-width:560px}\n}\n\n</style>\n<link rel="stylesheet" href="assets/workflow.css">\n<link rel="stylesheet" href="assets/office3d/canvas.css">\n</head>\n<body>\n<div id="scene"></div>\n<button id="resetCamera" class="camera-reset" aria-label="Kembalikan sudut pandang kantor">↗ Reset view</button>\n<div id="loading"><div>MEMBANGUN KANTOR 3D<span>Menyiapkan avatar, workstation, dan ruang trading…</span></div></div>\n<div class="top">\n <div class="brand"><div class="logo">⌁</div><div><strong>HARUN TRADING OFFICE</strong><small>● WORKER BELUM TERHUBUNG</small></div></div>\n <div class="stats">\n  <div class="stat"><span>Balance (USDT)</span><b>—</b></div>\n  <div class="stat"><span>PNL Hari Ini</span><b>—</b></div>\n  <div class="stat"><span>Fill Hari Ini</span><b>—</b></div>\n  <div class="stat"><span>Posisi Aktif</span><b>—</b></div>\n </div>\n</div>\n<button id="menuToggle" class="menu-toggle" aria-expanded="false">☰ <span>MENU</span></button>\n<div id="menuDrawer" class="menu-drawer" hidden>\n  <button id="robotMenu" data-view="robot" class="menu-item active">◉ <span>Robot Trading ON / OFF</span></button>\n  <button data-view="calendar" class="menu-item">▦ <span>Kalender PNL</span></button>\n  <div class="drawer-note">Pilih menu untuk membuka panel. Tampilan kantor tetap terlihat.</div>\n</div>\n<div id="infoPanel" class="panel info-panel" hidden><div class="panel-head"><h3 id="panelTitle">ROBOT TRADING ON / OFF</h3><button id="panelClose" class="panel-close" aria-label="Tutup panel">✕</button></div>\n<div id="panelContent">\n<p>Hubungkan worker untuk membaca akun dan status robot.</p>\n</div></div>\n<div class="bottomhint">Geser untuk memutar · Cubit untuk zoom</div>\n<script type="importmap">\n{\n  "imports": {\n    "three": "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js",\n    "three/addons/": "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"\n  }\n}\n</script>\n<script type="module" src="assets/office3d/renderer.js"></script>\n\n<script>\nwindow.addEventListener(\'error\', function(e) {\n  if (e.target && (e.target.tagName === \'SCRIPT\' || e.target.tagName === \'LINK\')) return;\n  const el = document.querySelector(\'#loading\');\n  if (el && el.style.display !== \'none\') {\n    el.innerHTML = \'<div>GAGAL MEMUAT KANTOR 3D<span>Modul 3D gagal dimuat. Periksa koneksi internet lalu muat ulang.</span></div>\';\n  }\n});\nwindow.addEventListener(\'unhandledrejection\', function(e) {\n  const el = document.querySelector(\'#loading\');\n  if (el) {\n    el.style.display = \'grid\';\n    el.innerHTML = \'<div>GAGAL MEMUAT KANTOR 3D<span>Modul 3D gagal dimuat. Periksa koneksi internet lalu muat ulang.</span></div>\';\n  }\n});\n</script>\n<script src="assets/dashboard.js"></script>\n</body>\n</html>\n', 'assets/dashboard.js': "/* Private worker dashboard. Credentials stay in tab memory; exchange work belongs to the server. */\n(() => {\n  'use strict';\n  const panel = document.getElementById('infoPanel');\n  const content = document.getElementById('panelContent');\n  const title = document.getElementById('panelTitle');\n  const drawer = document.getElementById('menuDrawer');\n  const menuToggle = document.getElementById('menuToggle');\n  const views = { robot: 'ROBOT TRADING ON / OFF', calendar: 'KALENDER PNL' };\n  const CALENDAR_START = '2026-10-01';\n  const FRESH_MS = 120000;\n  let origin = '', configuredOrigin = '', token = '', timer = null, snapshot = null;\n  let view = 'robot', generation = 0, revision = 0, polling = false, saving = false;\n  let riskDraft = null, resetRiskOnRefresh = null;\n  let online = false, refreshRequested = false, message = 'Hubungkan worker untuk membaca akun dan status robot.';\n  let calendarMonth = null, selectedDay = null;\n\n  function element(tag, text, className) {\n    const node = document.createElement(tag);\n    if (text !== undefined) node.textContent = String(text ?? '—').replace(/\\b(?:nanda|ai)\\b/gi, '').replace(/\\s+/g, ' ').trim();\n    if (className) node.className = className;\n    return node;\n  }\n  function number(value, digits = 2) {\n    if (value === null || value === undefined || value === '' || !Number.isFinite(Number(value))) return '—';\n    return Number(value).toLocaleString('en-US', { maximumFractionDigits: digits });\n  }\n  function timestamp(value) {\n    const time = typeof value === 'string' ? Date.parse(value) : NaN;\n    return Number.isFinite(time) && time <= Date.now() + 60000 ? time : null;\n  }\n  function fresh(value) { const time = timestamp(value); return time !== null && Date.now() - time >= -60000 && Date.now() - time < FRESH_MS; }\n  function date(value) {\n    const time = timestamp(value);\n    return time === null ? 'Belum tersedia' : new Date(time).toLocaleString('id-ID', { dateStyle: 'short', timeStyle: 'medium', timeZone: 'Asia/Jakarta' });\n  }\n  function validOrigin(value) {\n    const url = new URL(value);\n    if (url.protocol !== 'https:' || url.username || url.password || url.search || url.hash || url.pathname !== '/') throw Error('Gunakan origin HTTPS worker tanpa path atau kredensial.');\n    return url.origin;\n  }\n  function validRisk(value) {\n    const draft = value.trim(), match = /^(\\d+)(?:\\.(\\d+))?$/.exec(draft);\n    if (!match || draft.length > 64) throw Error('Risiko harus angka desimal lebih dari 0 sampai 100 USDT.');\n    const whole = match[1].replace(/^0+/, '') || '0', fraction = match[2] || '';\n    if (!/[1-9]/.test(whole+fraction) || whole.length > 3 ||\n        (whole.length === 3 && (whole > '100' || (whole === '100' && /[1-9]/.test(fraction))))) {\n      throw Error('Risiko harus lebih dari 0 dan maksimal 100 USDT.');\n    }\n    return draft;\n  }\n  const configUrl = new URL('worker-config.json', document.currentScript?.src || document.baseURI);\n  fetch(configUrl, { credentials: 'omit', cache: 'no-store' }).then(response => response.ok ? response.json() : null).then(config => {\n    if (config?.worker_origin) configuredOrigin = validOrigin(config.worker_origin);\n    else if (location.protocol === 'https:') configuredOrigin = location.origin;\n    const field = document.getElementById('apiOrigin');\n    if (field && !field.value && document.activeElement !== field) field.value = configuredOrigin;\n  }).catch(() => {});\n\n  function validate(data) {\n    if (!data || data.schema_version !== 2 || data.source !== 'BINANCE_FUTURES' || timestamp(data.generated_at) === null ||\n        !data.robot || typeof data.robot.robot_on !== 'boolean' || !data.account || !data.reports || !data.position_history ||\n        !Array.isArray(data.employees) || !Array.isArray(data.activity) || !Array.isArray(data.account.positions) || !Array.isArray(data.position_history.items)) {\n      throw Error('Respons dashboard worker tidak sesuai kontrak.');\n    }\n    if (data.employees.length > 50 || data.activity.length > 1000 || data.account.positions.length > 1000 || data.position_history.items.length > 10000) throw Error('Respons dashboard terlalu besar.');\n    return data;\n  }\n  function accountCurrent() { return online && snapshot?.account.status === 'CONNECTED' && fresh(snapshot.account.checked_at); }\n  function reportsCurrent() { return online && ['AVAILABLE', 'PARTIAL'].includes(snapshot?.reports.status) && fresh(snapshot.reports.checked_at); }\n  function publish() {\n    const account = accountCurrent() ? snapshot.account : null;\n    const reports = reportsCurrent() ? snapshot.reports : null;\n    const detail = {\n      source: 'BINANCE_FUTURES', schema_version: 2, status: online ? snapshot?.robot.bot_status ?? 'WAITING' : 'OFFLINE',\n      robot_on: online ? snapshot?.robot.robot_on ?? null : null,\n      robot_checked_at: online ? snapshot?.robot.checked_at ?? null : null,\n      account_checked_at: account?.checked_at ?? null,\n      reports_checked_at: reports?.checked_at ?? null,\n      risk_target_usdt: online ? snapshot?.robot.risk_target_usdt ?? null : null,\n      available_slots: online ? snapshot?.robot.available_slots ?? null : null,\n      manual_exposure: account && Array.isArray(snapshot?.robot.manual_exposure) ? [...snapshot.robot.manual_exposure] : [],\n      last_decision: online && snapshot?.robot.last_decision ? {\n        symbol: snapshot.robot.last_decision.symbol ?? null,\n        status: snapshot.robot.last_decision.status ?? null,\n        failure_code: snapshot.robot.last_decision.failure_code ?? null\n      } : null,\n      balance: account?.usdt_wallet_balance ?? null, usdt_wallet_balance: account?.usdt_wallet_balance ?? null,\n      active_positions: account?.active_positions ?? null, pnl_today: reports?.pnl_today_usdt ?? null,\n      trades_today: reports?.trades_today ?? null, generated_at: online ? snapshot?.generated_at : new Date().toISOString(),\n      events: online ? snapshot?.activity ?? [] : [], trades: [],\n      employees: online ? snapshot?.employees ?? [] : [], execution_gateway: online ? snapshot?.robot.execution_gateway ?? null : null\n    };\n    window.dispatchEvent(new CustomEvent('workerSnapshot', { detail }));\n  }\n  function paintStats() {\n    const account = accountCurrent() ? snapshot.account : null;\n    const reports = reportsCurrent() ? snapshot.reports : null;\n    const values = [number(account?.usdt_wallet_balance), number(reports?.pnl_today_usdt), number(reports?.trades_today, 0), number(account?.active_positions, 0)];\n    document.querySelectorAll('.stats .stat b').forEach((node, index) => { node.textContent = values[index]; });\n    document.querySelectorAll('.stats .stat b')[1]?.classList.toggle('positive', reports?.pnl_today_usdt !== null && reports?.pnl_today_usdt !== undefined && Number(reports.pnl_today_usdt) >= 0);\n    const pnlLabel = document.querySelectorAll('.stats .stat span')[1];\n    if (pnlLabel) pnlLabel.textContent = reports?.complete === false ? 'PNL Hari Ini *' : 'PNL Hari Ini';\n    const pnlValue = document.querySelectorAll('.stats .stat b')[1];\n    if (pnlValue) pnlValue.title = reports?.complete === false ? 'Data Binance parsial; rincian posisi ditutup tersedia pada Kalender PNL.' : '';\n    document.querySelector('.brand small').textContent = !origin ? '● WORKER BELUM TERHUBUNG' : !online ? '● WORKER TIDAK TERJANGKAU' : !account ? '● AKUN BINANCE BELUM TERSEDIA' : '● BINANCE FUTURES · '+(snapshot.robot.robot_on ? 'ROBOT ON' : 'ROBOT OFF');\n    const robotMenu = document.getElementById('robotMenu');\n    robotMenu.dataset.robotOn = snapshot ? String(snapshot.robot.robot_on) : '';\n    robotMenu.dataset.status = online ? snapshot?.robot.bot_status ?? 'WAITING' : 'OFFLINE';\n  }\n  function notice(text, tone = 'normal') { return element('p', text, 'dashboard-notice '+tone); }\n  function section(label) {\n    const node = element('section', undefined, 'dashboard-section'); node.append(element('h4', label)); return node;\n  }\n  function field(container, label, value) {\n    const row = element('div', undefined, 'dashboard-field'); row.append(element('span', label), element('b', value)); container.append(row);\n  }\n  function source(container, data, unavailable = 'Data belum tersedia dari worker.') {\n    const good = data && ['AVAILABLE', 'PARTIAL', 'CONNECTED'].includes(data.status);\n    container.append(notice(good ? `Binance Futures · Diperiksa ${date(data.checked_at)}${data.complete === false ? ' · Data parsial' : ''}` : unavailable, good && fresh(data.checked_at) && online ? 'normal' : 'warning'));\n    if (good && (!fresh(data.checked_at) || !online)) container.append(notice('Data terakhir sudah lama atau worker tidak terjangkau. Angka ini bukan pembaruan terkini.', 'warning'));\n  }\n  function gatewayNote(robot) {\n    const gateway = robot?.execution_gateway;\n    if (!online || !gateway) return notice('Status gateway belum tersedia dari worker.', 'warning');\n    if (!gateway?.connected || ['NOT_CONNECTED', 'BLOCKED', 'UNAVAILABLE'].includes(gateway.status)) {\n      return notice('Transport pengiriman order Binance belum tersedia · '+(gateway?.failure_code || 'BINANCE_ORDER_GATEWAY_NOT_CONNECTED')+'. Worker belum dapat mengirim order ke Binance.', 'warning');\n    }\n    return notice('Gateway eksekusi: '+(gateway.status ?? 'BELUM DIKETAHUI')+'. Riwayat Binance menjadi bukti transaksi yang terjadi.');\n  }\n  function renderRobot() {\n    const robot = snapshot?.robot, account = snapshot?.account;\n    const main = section('COORDINATOR 24/7');\n    const actions = element('div', undefined, 'dashboard-actions');\n    const toggle = element('button', 'ROBOT TRADING: '+(robot ? robot.robot_on ? 'ON' : 'OFF' : 'BELUM TERHUBUNG'));\n    toggle.id = 'robotToggle'; toggle.disabled = !origin || !online || saving || !robot;\n    toggle.setAttribute('aria-pressed', String(robot?.robot_on === true));\n    toggle.onclick = () => saveSettings({ robot_on: !snapshot.robot.robot_on }); actions.append(toggle); main.append(actions);\n    main.append(element('p', message, 'dashboard-message'));\n    const riskControls = element('div', undefined, 'dashboard-connection dashboard-risk');\n    const riskLabel = element('label', 'RISIKO PER SL TERMASUK FEE DAN CADANGAN SLIPPAGE (USDT, lebih dari 0 sampai 100)');\n    const risk = element('input'); risk.id = 'robotRisk'; risk.type = 'number'; risk.inputMode = 'decimal';\n    risk.min = '0'; risk.max = '100'; risk.step = 'any'; risk.value = riskDraft ?? robot?.risk_target_usdt ?? '5';\n    risk.disabled = !origin || !online || saving || !robot; risk.oninput = () => { riskDraft = risk.value; };\n    riskLabel.append(risk);\n    const riskActions = element('div', undefined, 'dashboard-actions'), riskSave = element('button', 'SIMPAN RISIKO');\n    riskSave.id = 'robotRiskSave'; riskSave.disabled = risk.disabled;\n    riskSave.onclick = () => {\n      try { riskDraft = risk.value; saveSettings({ risk_target_usdt: validRisk(risk.value) }); }\n      catch (error) { message = error.message; paint(); }\n    };\n    riskActions.append(riskSave); riskControls.append(riskLabel, riskActions,\n      notice('Ukuran posisi dihitung mendekati batas risiko, termasuk fee entry, fee exit, dan cadangan slippage exit 0,5%. Gap atau slippage yang melampaui cadangan serta funding dapat membuat kerugian aktual melebihi batas. Perubahan risiko berlaku hanya untuk analisis baru; setup dan intent yang sudah dibuat tetap memakai risiko sebelumnya.'));\n    main.append(riskControls);\n    const status = element('p', robot ? 'BOT STATUS: '+robot.bot_status+(robot.wait_reason ? ' · WAIT: '+robot.wait_reason : '')+(robot.failure_code ? ' · '+robot.failure_code : '') : 'Menunggu status worker.', 'dashboard-status');\n    status.id = 'robotStatus'; status.setAttribute('role', 'status'); main.append(status);\n    const metrics = element('div', undefined, 'dashboard-metrics');\n    field(metrics, 'Risk per SL', number(robot?.risk_target_usdt)+' USDT');\n    field(metrics, 'Posisi / kapasitas', number(account?.active_positions, 0)+' / 2');\n    field(metrics, 'Slot tersedia', number(robot?.available_slots, 0));\n    field(metrics, 'Entry bot hari ini', number(robot?.bot_entries_today, 0)+' / 2');\n    main.append(metrics, gatewayNote(robot));\n    main.append(notice('Maksimal 2 entry bot per hari WIB. Posisi bawaan dari hari sebelumnya dan posisi manual tetap memakai slot dari kapasitas 2 coin. Order entry yang belum terisi juga memakai slot.'));\n    main.append(notice('ON menjalankan coordinator ketika slot tersedia. OFF menghentikan riset, pengiriman order baru, dan rekonsiliasi robot. Pemasangan TP/SL serta pembatalan order oleh robot juga berhenti. Posisi serta order yang sudah ada tetap di Binance dan dapat terisi; OFF tidak menutup posisi atau membatalkan order. Dashboard tetap dapat membaca saldo dan posisi.'));\n    if (robot?.last_decision) main.append(notice('Keputusan terakhir: '+robot.last_decision.symbol+' · '+robot.last_decision.status+(robot.last_decision.failure_code ? ' · '+robot.last_decision.failure_code : '')));\n    content.append(main);\n    const current = section('AKUN FUTURES'); source(current, account);\n    const details = element('div', undefined, 'dashboard-metrics');\n    field(details, 'Wallet USDT', number(account?.usdt_wallet_balance)); field(details, 'USDT tersedia', number(account?.usdt_available_balance));\n    field(details, 'Posisi manual', Array.isArray(robot?.manual_exposure) && robot.manual_exposure.length ? robot.manual_exposure.join(', ') : '—');\n    current.append(details);\n    if (account?.positions?.length) for (const row of account.positions) {\n      const position = element('article', undefined, 'dashboard-row');\n      position.append(element('strong', row.symbol+' · '+row.side), element('p', `Quantity ${number(row.quantity, 8)} · Entry ${number(row.entry_price, 8)} · Mark ${number(row.mark_price, 8)} · Unrealized PnL ${number(row.unrealized_pnl)} USDT`)); current.append(position);\n    }\n    else current.append(notice(account?.status === 'CONNECTED' ? 'Tidak ada posisi aktif yang dilaporkan Binance.' : 'Posisi aktif belum tersedia.'));\n    content.append(current, renderConnection());\n  }\n  function renderConnection() {\n    const details = element('details', undefined, 'dashboard-connection'); details.open = !origin;\n    details.append(element('summary', 'Koneksi worker privat'));\n    const originLabel = element('label', 'Origin HTTPS worker');\n    const originField = element('input'); originField.id = 'apiOrigin'; originField.type = 'url'; originField.value = origin || configuredOrigin; originField.placeholder = 'https://worker-anda'; originField.autocomplete = 'url';\n    originLabel.append(originField);\n    const tokenLabel = element('label', 'Token kontrol worker');\n    const tokenField = element('input'); tokenField.id = 'apiToken'; tokenField.type = 'password'; tokenField.autocomplete = 'off'; tokenField.placeholder = 'Token worker · bukan API key';\n    tokenLabel.append(tokenField);\n    const actions = element('div', undefined, 'dashboard-actions');\n    const connect = element('button', 'HUBUNGKAN WORKER'); connect.id = 'apiConnect';\n    connect.onclick = () => {\n      try {\n        const nextOrigin = validOrigin(originField.value.trim()), nextToken = tokenField.value.trim();\n        if (nextToken.length < 32) throw Error('Token kontrol minimal 32 karakter.');\n        disconnect(); origin = nextOrigin; token = nextToken; tokenField.value = ''; message = 'Menghubungkan worker…';\n        paint(); poll(); timer = setInterval(poll, 5000);\n      } catch (error) { message = err