generation, currentRevision = revision; polling = true;\n    try {\n      const data = validate(await request('/office/status'));\n      if (currentGeneration !== generation || currentRevision !== revision || saving) return;\n      snapshot = data; online = true;\n      if (resetRiskOnRefresh !== null) {\n        if (riskDraft === resetRiskOnRefresh) riskDraft = null;\n        resetRiskOnRefresh = null;\n      }\n      message = 'Worker terhubung · Diperiksa '+date(data.generated_at); publish(); paint();\n    } catch (error) {\n      if (currentGeneration !== generation || currentRevision !== revision) return;\n      online = false; message = error.message+'. Data terakhir bukan pembaruan terkini.'; publish(); paint();\n    } finally {\n      if (currentGeneration === generation) {\n        polling = false;\n        if (refreshRequested && !saving) { refreshRequested = false; poll(); }\n      }\n    }\n  }\n  async function saveSettings(value) {\n    if (!origin || !online || saving || !snapshot) return;\n    const riskChange = typeof value.risk_target_usdt === 'string';\n    const currentGeneration = generation; revision++; saving = true; message = riskChange ? 'Menyimpan risiko untuk analisis baru…' : 'Menyimpan status robot…'; paint();\n    try {\n      await request('/robot/settings', 'POST', value);\n      if (currentGeneration !== generation) return;\n      if (riskChange) resetRiskOnRefresh = value.risk_target_usdt;\n      message = riskChange ? 'Risiko tersimpan untuk analisis baru. Membaca pembaruan worker…' : 'Status tersimpan. Membaca pembaruan worker…';\n    } catch (error) { if (currentGeneration === generation) message = error.message+'. Pengaturan belum dapat dipastikan.'; }\n    finally {\n      if (currentGeneration === generation) {\n        saving = false; refreshRequested = true; paint();\n        if (!polling) { refreshRequested = false; poll(); }\n      }\n    }\n  }\n  function disconnect() {\n    generation++; revision++; clearInterval(timer); timer = null; token = ''; origin = ''; snapshot = null;\n    polling = false; saving = false; refreshRequested = false; online = false;\n    riskDraft = null; resetRiskOnRefresh = null; calendarMonth = null; selectedDay = null;\n    const field = document.getElementById('apiToken'); if (field) field.value = ''; publish();\n  }\n  menuToggle.addEventListener('click', () => { drawer.hidden = !drawer.hidden; menuToggle.setAttribute('aria-expanded', String(!drawer.hidden)); });\n  drawer.querySelectorAll('[data-view]').forEach(button => button.addEventListener('click', () => {\n    view = button.dataset.view; drawer.querySelectorAll('[data-view]').forEach(item => item.classList.toggle('active', item === button));\n    panel.hidden = false; panel.scrollTop = 0; drawer.hidden = true; menuToggle.setAttribute('aria-expanded', 'false'); paint();\n  }));\n  document.getElementById('panelClose').addEventListener('click', () => { panel.hidden = true; });\n  document.addEventListener('visibilitychange', () => { if (!document.hidden) { publish(); paint(); poll(); } });\n  window.addEventListener('pagehide', () => { disconnect(); });\n  paintStats();\n})();\n", 'assets/workflow.css': '/* Dashboard overlays sit above the read-only 3D office. */\n.info-panel{overflow-x:hidden}\n.dashboard-section{padding:14px;border:1px solid var(--line);background:#25464b45;border-radius:12px;margin:14px 0;overflow-wrap:anywhere}\n.dashboard-section h4{font-size:11px;letter-spacing:.08em;color:#c1e6e4;margin:0 0 12px}\n.dashboard-actions{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}\n.dashboard-actions button{min-height:44px;padding:11px 14px;background:#365e68;border:1px solid var(--line);border-radius:9px;color:#eff6ff;font:inherit;font-size:12px;font-weight:600}\n.dashboard-actions button:disabled{opacity:.45;cursor:default}\n#robotToggle{flex:1;text-align:center;letter-spacing:.04em}\n#robotToggle[aria-pressed=true]{background:#215a48;border-color:#a0e0bd77;color:#c3ffe1}\n.dashboard-notice,.dashboard-message,.dashboard-status{font-size:12px;line-height:1.6;overflow-wrap:anywhere;margin:9px 0;color:#c4d8dd}\n.dashboard-notice.warning{color:#ffe0a3;padding:10px;border-left:3px solid #deb670;background:#795f2220;border-radius:0 7px 7px 0}\n.dashboard-status{font-weight:600;color:#e0f1f5}\n.dashboard-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 16px}\n.dashboard-field{display:flex;flex-wrap:wrap;justify-content:space-between;gap:5px 16px;padding:8px 0;border-bottom:1px solid #ffffff12;font-size:12px;line-height:1.5;min-width:0}\n.dashboard-field span{color:var(--muted)}.dashboard-field b{font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.dashboard-row{padding:12px 0;border-bottom:1px solid #ffffff18;overflow-wrap:anywhere}\n.dashboard-row:last-child{border-bottom:0}.dashboard-row strong{display:block;font-size:12px;line-height:1.5;color:#e0f0f5}\n.dashboard-row p{margin:5px 0;font-size:11px;line-height:1.6;color:#b7cfd6}.dashboard-row small{display:block;font-size:10px;color:#90adb8;margin:4px 0}\n.dashboard-connection{font-size:12px;line-height:1.6;margin:15px 0;border-top:1px solid var(--line);padding-top:4px}\n.dashboard-connection summary{cursor:pointer;padding:12px 0;min-height:44px;color:#d4e8ec}\n.dashboard-connection label{display:block;margin-top:8px;color:#c9dce0}\n.dashboard-connection input{display:block;width:100%;min-height:44px;padding:10px;background:#122934;border:1px solid var(--line);border-radius:8px;color:#fff;font-size:16px;margin-top:4px}\n@media(max-width:700px){.dashboard-section{padding:12px;margin:11px 0}.dashboard-metrics{grid-template-columns:1fr}.dashboard-field{font-size:11px}}\n\n/* A monthly closed-position calendar, with no decorative account numbers. */\n.info-panel.calendar-panel{width:min(920px,calc(100vw - 32px));max-height:calc(100dvh - 180px);background:rgba(16,21,25,.98);border-color:#3b454a;padding:18px;color:#e6ebed}\n.calendar-panel .panel-head{position:sticky;top:-18px