ay{display:flex;flex-direction:column;align-items:stretch;justify-content:flex-end;text-align:left;position:relative;min-width:0;min-height:86px;padding:28px 9px 10px;border:1px solid #293235;border-radius:8px;background:#181e20;color:#dbe4e7;font-family:inherit;box-shadow:inset 0 1px 0 #ffffff04}\n.pnl-day-number{position:absolute;right:8px;top:8px;font-size:11px;line-height:1;color:#83959c}\n.pnl-day-value{font-size:13px;line-height:1.35;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-variant-numeric:tabular-nums;font-weight:650}\n.pnl-day-count{font-size:9px;color:#809097;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pnl-day.profit{background:radial-gradient(ellipse at 50% 130%,#1d664249 0%,transparent 90%),linear-gradient(150deg,#182d20,#16251e);border-color:#2a5036}\n.pnl-day.loss{background:radial-gradient(ellipse at 50% 130%,#6e242649 0%,transparent 90%),linear-gradient(150deg,#301d1e,#25191b);border-color:#523234}\n.pnl-day.profit .pnl-day-value,.pnl-profit-text{color:#5fe29d}\n.pnl-day.loss .pnl-day-value,.pnl-loss-text{color:#f16b77}\n.pnl-day.profit .pnl-day-count{color:#8da899}.pnl-day.loss .pnl-day-count{color:#ac9295}\n.pnl-day[aria-pressed=true]{border-color:#b8cace;box-shadow:0 0 0 1px #b8cace}\n.pnl-day[aria-current=date] .pnl-day-number{color:#e1ecef;font-weight:700}\n.pnl-day:disabled{opacity:.32;cursor:default}\n.pnl-day-detail{padding:0 2px 4px}\n.pnl-day-detail>h4{margin:0 0 12px;font-size:13px;font-weight:600;text-transform:capitalize;color:#c5d1d6}\n.pnl-position{padding:18px 0;border-top:1px solid #354048}\n.pnl-position-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:18px}\n.pnl-position-identity{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.pnl-position-identity strong{font-size:16px;font-weight:650;color:#e8edef}\n.pnl-side{display:grid;place-items:center;width:20px;height:20px;border-radius:4px;font-size:12px;color:#f2fff8;font-weight:700}\n.pnl-side.long{background:#26af7a}.pnl-side.short{background:#d7465e}\n.pnl-badge{font-size:10px;padding:2px 5px;background:#303b44;border-radius:4px;color:#becbd1}\n.pnl-closed{font-size:11px;color:#adbcc4;white-space:nowrap;padding-top:4px}\n.pnl-position-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 12px;margin-bottom:15px}\n.pnl-position-metric{display:flex;flex-direction:column;gap:7px;min-width:0}\n.pnl-position-metric>span{font-size:11px;line-height:1.4;color:#899ca7}\n.pnl-position-metric>b{font-size:17px;font-weight:550;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}\n.pnl-position-times .dashboard-field{font-size:11px;border:0;padding:4px 0}\n.pnl-position-times .dashboard-field span{color:#8e9faa}\n.pnl-position-times .dashboard-field b{font-weight:400;color:#abbcc5}\n.pnl-fees{color:#7d909b;font-size:10px;line-height:1.6;margin:10px 0 0}\n@media(max-width:700px){\n .info-panel.calendar-panel{width:calc(100vw - 20px);max-height:calc(100dvh - 178px - env(safe-area-inset-top));padding:13px}\n .calendar-panel .panel-head{top:-13px;padding:4px 0 12px}\n .pnl-calendar{padding:12px;border-radius:11px}\n .pnl-calendar-head{gap:8px;margin-bottom:15px}\n .pnl-calendar-heading{gap:7px}.pnl-calendar-heading h4{font-size:13px}.pnl-calendar-icon{font-size:19px}\n .pnl-month-navigation{gap:0}.pnl-month-navigation strong{font-size:10px;min-width:105px}.pnl-month-navigation button{width:34px}\n .pnl-summary{gap:8px}.pnl-summary span{font-size:10px}.pnl-summary strong{font-size:18px}\n .pnl-weekdays,.pnl-grid{gap:4px}.pnl-weekdays{font-size:9px;margin-top:15px}.pnl-weekdays span{padding-left:3px}\n .pnl-day{min-height:60px;padding:23px 4px 7px;border-radius:6px}.pnl-day-number{font-size:10px;right:5px;top:6px}.pnl-day-value{font-size:10px;letter-spacing:-.02em}.pnl-day-count{font-size:8px;margin-top:5px}\n .pnl-source,.pnl-method,.pnl-legend{font-size:10px}.pnl-calendar .dashboard-notice.warning{font-size:10px;padding:8px}\n .pnl-position{padding:16px 0}.pnl-position-identity strong{font-size:14px}.pnl-position-metric>b{font-size:15px}.pnl-position-metric>span{font-size:10px}.pnl-position-times .dashboard-field{font-size:10px;gap:4px 8px}\n}\n@media(max-width:370px){.pnl-calendar-head{justify-content:center}.pnl-calendar-heading{margin-right:auto}.pnl-day-value{font-size:9px}.pnl-day-count{font-size:7px}.pnl-day{padding-left:3px;padding-right:3px}}\n', 'harun_ai_trading_office_3d_detailed.html': '<!doctype html>\n<html lang="id">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta http-equiv="refresh" content="0;url=./">\n  <link rel="canonical" href="./">\n  <title>HARUN Trading Office</title>\n</head>\n<body>\n  <p>Alamat kantor tetap tersedia melalui <a href="./">HARUN Trading Office</a>.</p>\n</body>\n</html>\n', 'assets/office3d/scene-builder.js': "import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';\nimport { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';\nimport {\n  BOUNDS, STATION_CONFIG, COLLIDERS, SOFA_CONFIG, PLANT_CONFIG,\n  STORAGE_CONFIG, LOUNGE_SLOTS, SOCIAL_SLOTS,\n} from './layout.js';\n\n// Static furniture is constructed in local coordinates and then merged by material.\n// Monitor textures stay separate so presentation updates never rebuild the room.\nexport function createOfficeScene(THREE, { scene, monitors, mobile = false }) {\n  const root = new THREE.Group(); root.name = 'harun-office-architecture'; scene.add(root);\n  const staticRoot = new THREE.Group(); root.add(staticRoot);\n  const displays = new THREE.Group(); displays.name = 'office-displays'; root.add(displays);\n  const materials = new Map(), geometries = new Map(), ownTextures = new Set();\n  const stationary = {}, displayMeshes = [];\n  const mat = (color, roughness = .65, metalness = 0) => {\n    const key = `${color}:${roughness}:${metalness}`;\n    if (!materials.has(key)) materials.set(key, new THREE.MeshStandardMaterial({ color, roughness, metalness }));\n    return materials.get(key);\n  };\n  const M = {\n    oak: mat('#c59b70'), edge: mat('#9d7852'), white: mat('#eef0eb'), wall: mat('#dce2df'),\n    steel: mat('#81969b', .3, .65), dark: mat('#223740'), chair: mat('#304b57'),\n    seat: mat('#55747b', .88), textile: mat('#9aada9', .9), leaf: mat('#477657', .86),\n    leafLight: mat('#77a777', .86), soil: mat('#514336'), blue: mat('#173747', .5),\n    carpet: mat('#a9bbb9', .98), brass: mat('#a98b5c', .33, .58),\n  };\n  M.glass = new THREE.MeshStandardMaterial({ color: '#bcd7dc', transparent: true, opacity: .20, roughness: .18, metalness: .05, depthWrite: false });\n  M.glow = new THREE.MeshBasicMaterial({ color: '#fff0cd' });\n  materials.set('glass', M.glass); materials.set('glow', M.glow);\n  const geo = (key, factory) => { if (!geometries.has(key)) geometries.set(key, factory()); return geometries.get(key); };\n  const add = (parent, geometry, material, position, scale) => {\n    const mesh = new THREE.Mesh(geometry, material);\n    if (position) mesh.position.set(...position);\n    if (scale) mesh.scale.set(...scale);\n    mesh.castShadow = material !== M.glass && material !== M.glow;\n    mesh.receiveShadow = material !== M.glass; parent.add(mesh); return mesh;\n  };\n  const block = (parent, position, size, material, radius = .035) => add(parent,\n    geo(`box:${size.join(',')}:${radius}`, () => radius ?\n      new RoundedBoxGeometry(...size, mobile ? 1 : 2, Math.min(radius, ...size.map(n => n / 2))) : new THREE.BoxGeometry(...size)),\n    material, position);\n  const sphere = geo('sphere', () => new THREE.SphereGeometry(1, mobile ? 10 : 14, mobile ? 8 : 10));\n  const cylinder = geo('cylinder', () => new THREE.CylinderGeometry(1, 1, 1, mobile ? 10 : 14));\n  const ellipse = (parent, position, scale, material) => add(parent, sphere, material, position, scale);\n  const rod = (parent, from, to, radius, material) => {\n    const a = new THREE.Vector3(...from), b = new THREE.Vector3(...to), direction = b.clone().sub(a);\n    const mesh = add(parent, cylinder, material, a.clone().add(b).multiplyScalar(.5).toArray(), [radius, direction.length(), radius]);\n    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize()); return mesh;\n  };\n  const canvasTexture = (width, height, paint) => {\n    const canvas = document.createElement('canvas'); canvas.width = width; canvas.height = height;\n    paint(canvas.getContext('2d'), width, height);\n    const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;\n    ownTextures.add(texture); return texture;\n  };\n  const label = (position, width, height, lines, accent = '#b8d9d4', rotation = 0, background = '#223a44') => {\n    const texture = canvasTexture(1024, 256, (ctx, w, h) => {\n      ctx.fillStyle = background; ctx.fillRect(0, 0, w, h);\n      ctx.fillStyle = accent; ctx.fillRect(0, 0, 10, h);\n      ctx.font = '600 48px Arial'; ctx.fillText(lines[0], 38, 102);\n      ctx.font = '400 27px Arial'; ctx.fillStyle = '#a6bdc3';\n      if (lines[1]) ctx.fillText(lines[1], 38, 167);\n    });\n    const material = new THREE.MeshBasicMaterial({ map: texture }); materials.set(`label:${materials.size}`, material);\n    const mesh = add(displays, geo(`plane:${width}:${height}`, () => new THREE.PlaneGeometry(width, height)), material, position);\n    mesh.rotation.y = rotation; mesh.castShadow = false; displayMeshes.push(mesh); return mesh;\n  };\n\n  // A floating platform and locally generated oak planks give the cutaway room depth.\n  block(staticRoot, [0, -.25, 1], [22.1, .5, 20.75], M.white, .16);\n  block(staticRoot, [0, -.04, 1], [21.9, .10, 20.55], M.edge, .04);\n  const floorTexture = canvasTexture(512, 512, ctx => {\n    ctx.fillStyle = '#cfb495'; ctx.fillRect(0, 0, 512, 512);\n    for (let y = 0; y < 512; y += 64) {\n      ctx.fillStyle = y % 128 ? '#d1ba9e' : '#c6aa88'; ctx.fillRect(0, y, 512, 