b(leg, _target, leg.pole, 0.47, 0.47);\n      // Keep the shoe flat in root space even while knee/hip bones rotate.\n      leg.ankle.quaternion.copy(leg.pivot.quaternion).multiply(leg.middle.quaternion).invert();\n    }\n    lastPose = { state, sit: sitting, seatHeight, weights: { ...weights }, walkSpeed: speed, reducedMotion: reduced };\n    root.updateMatrixWorld(true);\n  }\n\n  function diagnostics() {\n    let meshes = 0, joints = 0;\n    root.traverse((node) => { if (node.isMesh) meshes += 1; else if (node.isGroup) joints += 1; });\n    const world = new THREE.Vector3();\n    return { id: root.userData.id, role, disposed, meshes, joints,\n      sharedGeometries: geometries.size, sharedMaterials: materials.size,\n      ...lastPose, headHeight: head.getWorldPosition(world).y,\n      footHeights: legs.map((leg) => leg.ankle.getWorldPosition(new THREE.Vector3()).y - 0.065),\n      animation: 'ARTICULATED_CLIP_BLEND', forward: '+Z' };\n  }\n  function dispose() {\n    if (disposed) return;\n    disposed = true;\n    root.removeFromParent();\n    for (const item of owned) item.dispose();\n    users -= 1;\n    if (!users) {\n      for (const item of geometries.values()) item.dispose();\n      for (const item of materials.values()) item.dispose();\n      geometries = new Map();\n      materials = new Map();\n    }\n  }\n  pose(0, 0, { state: 'IDLE', sit: 1 });\n  return { root, headAnchor, pose, dispose, diagnostics, blender };\n}\n"}
"""OFF-only, read-only journal and exchange verification for one source update."""
import argparse
import fcntl
import hashlib
import json
import os
import re
import sqlite3
import stat
import sys
import tempfile
import time
from datetime import datetime, timezone
from decimal import Decimal
from pathlib import Path

UID = 10001
CACHE_TABLES = frozenset(('robot_status', 'office_cache', 'office_activity'))

class Refuse(Exception):
    pass

def require(value, reason):
    if not value:
        raise Refuse(reason)

def private_file(path):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        info = os.fstat(fd)
        require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1 and
                info.st_uid == os.geteuid() == UID and not info.st_mode & 0o077,
                'JOURNAL_FILE_INVALID')
        return fd, (info.st_dev, info.st_ino)
    except BaseException:
        os.close(fd)
        raise

def directories(path):
    for part in (path, *path.parents):
        require(stat.S_ISDIR(part.lstat().st_mode), 'JOURNAL_DIRECTORY_INVALID')

def pinned(path, identity):
    info = path.lstat()
    require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1 and
            (info.st_dev, info.st_ino) == identity, 'JOURNAL_PATH_CHANGED')

def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':')).encode()).hexdigest()

def typed(value):
    if value is None:
        return ['null']
    if type(value) is int:
        return ['int', str(value)]
    if type(value) is float:
        return ['float', value.hex()]
    if isinstance(value, bytes):
        return ['bytes', value.hex()]
    if isinstance(value, str):
        return ['str', value]
    raise Refuse('JOURNAL_VALUE_INVALID')

def snapshot(db):
    """Exclude only display caches; retain every existing financial/research row."""
    require(db.execute('PRAGMA integrity_check').fetchall() == [('ok',)], 'JOURNAL_INVALID')
    require(not db.execute("SELECT 1 FROM sqlite_master WHERE type='trigger'").fetchone(),
            'JOURNAL_TRIGGER_PRESENT')
    require(db.execute('SELECT enabled FROM robot_settings WHERE id=1').fetchall() == [(0,)],
            'ROBOT_OFF_REQUIRED')
    require(db.execute('SELECT version FROM office_schema').fetchall() == [(2,)],
            'JOURNAL_MIGRATION_REQUIRED')
    require(not db.execute("SELECT 1 FROM order_intents WHERE state IN ('SUBMITTING','NEEDS_REVIEW') LIMIT 1").fetchone(),
            'UNRESOLVED_ORDER')
    tables = [r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
    require({'robot_settings', 'order_intents', 'api_requests', 'robot_cycles',
             'robot_jobs', 'robot_candidates', 'robot_entry_receipts'} <= set(tables),
            'JOURNAL_SCHEMA_INVALID')
    records = []
    counts = {}
    for name in tables:
        require(re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]{0,99}', name), 'JOURNAL_SCHEMA_INVALID')
        if name in CACHE_TABLES:
            continue
        rows = sorted(json.dumps([typed(v) for v in row], separators=(',', ':'))
                      for row in db.execute('SELECT * FROM "' + name + '"'))
        schema = sorted(tuple(row) for row in db.execute(
            'SELECT type,name,sql FROM sqlite_master WHERE tbl_name=? ORDER BY type,name', (name,)))
        records.append([name, schema, rows])
        counts[name] = len(rows)
    for table in ('api_requests', 'robot_jobs'):
        require(not db.execute('SELECT 1 FROM "' + table + '" WHERE state IN (?,?) LIMIT 1', ('PENDING','NEEDS_REVIEW')).fetchone(),
                'UNRESOLVED_PROVIDER_REQUEST')
    settings = db.execute('SELECT enabled,risk FROM robot_settings WHERE id=1').fetchone()
    require(isinstance(settings[1], str) and re.fullmatch(r'[0-9]+(?:\.[0-9]+)?', settings[1]) and
            Decimal('0') < Decimal(settings[1]) <= Decimal('100'), 'RISK_SETTING_INVALID')
    states = dict(db.execute('SELECT state,count(*) FROM order_intents GROUP BY state'))
    require(all(re.fullmatch(r'[A-Z_]{1,60}', k) for k in states), 'JOURNAL_STATE_INVALID')
    return dict(journal_sha256=digest(records), table_counts=counts,
                robot_on=False, risk_target_usdt=settings[1], order_states=states)

def verify_sources(expected, root):
    root = Path(root).absolute()
    directories(root)
    paths = list((root / 'worker').rglob('*.py')) + [root / 'deploy/container_boot.py', root / 'deploy/runtime_permissions.py']
    require(set(expected) == {str(p.relative_to(root)) for p in paths}, 'SOURCE_INVENTORY_CHANGED')
    for name, sha in expected.items():
        require(re.fullmatch(r'(?:worker|deploy)/(?:[A-Za-z0-9_]+/)*[A-Za-z0-9_]+\.py', name)
                and re.fullmatch(r'[a-f0-9]{64}', sha), 'SOURCE_MAP_INVALID')
        p = root / name
        directories(p.parent)
        fd = os.open(p, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        try:
            info = os.fstat(fd)
            require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1 and info.st_size < 2_000_000,
                    'SOURCE_PATH_INVALID')
            with os.fdopen(os.dup(fd), 'rb') as stream:
                require(hashlib.sha256(stream.read(2_000_001)).hexdigest() == sha, 'SOURCE_CHANGED')
        finally:
            os.close(fd)

def clean_scalar(value, *, number=False):
    require(isinstance(value, str) and re.fullmatch(r'[A-Za-z0-9_.:-]{1,100}', value),
            'EXCHANGE_OBSERVATION_INVALID')
    if number:
        require(Decimal(value).is_finite(), 'EXCHANGE_OBSERVATION_INVALID')
    return value

def exchange_snapshot(reader=None):
    # BinanceReadOnly has no configurable HTTP method/body and its transport
    # validates the fixed Futures origin and GET allowlist independently.
    if reader is None:
        from worker.binance_private import BinanceReadOnly
        reader = BinanceReadOnly()
    reader.sync_time()
    positions = reader.signed_get('/fapi/v3/positionRisk')
    orders = reader.signed_get('/fapi/v1/openOrders')
    algos = reader.signed_get('/fapi/v1/openAlgoOrders')
    require(all(isinstance(v, list) and len(v) <= 10_000 for v in (positions, orders, algos)),
            'EXCHANGE_OBSERVATION_INVALID')
    active = []
    for row in positions:
        require(isinstance(row, dict), 'EXCHANGE_OBSERVATION_INVALID')
        amount = clean_scalar(row.get('positionAmt'), number=True)
        if Decimal(amount) == 0:
            continue
        active.append(dict(symbol=clean_scalar(row.get('symbol')),
                           position_side=clean_scalar(row.get('positionSide')),
                           quantity=amount))
    def brief(rows, algo):
        result = []
        for row in rows:
            require(isinstance(row, dict), 'EXCHANGE_OBSERVATION_INVALID')
            identity = row.get('algoId' if algo else 'orderId')
            require(type(identity) is int and identity > 0 or isinstance(identity, str) and re.fullmatch(r'[1-9][0-9]{0,24}', identity),
                    'EXCHANGE_OBSERVATION_INVALID')
            result.append(dict(symbol=clean_scalar(row.get('symbol')),
                               id=str(identity), status=clean_scalar(row.get('algoStatus' if algo else 'status')),
                               side=clean_scalar(row.get('side')),
                               order_type=clean_scalar(row.get('orderType' if algo else 'type'))))
        return sorted(result, key=lambda v: (v['symbol'], v['id']))
    result = dict(active_positions=sorted(active, key=lambda v:(v['symbol'],v['position_side'])),
                  open_orders=brief(orders, False), open_algos=brief(algos, True))
    result['get_only'] = True
    return result

def fresh_off(db, cutoff):
    require(db.execute('SELECT enabled FROM robot_settings WHERE id=1').fetchall() == [(0,)],
            'ROBOT_OFF_REQUIRED')
    row = db.execute('SELECT data FROM robot_status WHERE id=1').fetchone()
    if not row:
        return False
    data = json.loads(row[0])
    value = data.get('checked_at')
    if not isinstance(value, str):
        return False
    stamp = datetime.fromisoformat(value.replace('Z', '+00:00'))
    return (stamp.tzinfo is not None and stamp.timestamp() >= cutoff and
            data.get('bot_status') == 'OFF' and data.get('wait_reason') == 'ROBOT_OFF' and
            data.get('failure_code') is None)

def inspect(data_dir='/data', *, expected=None, root='/app', before=None, backup=False,
            exchange=False, fresh_after=None):
    require(os.geteuid() == UID, 'WORKER_UID_REQUIRED')
    directory = Path(data_dir).absolute() / 'trading'
    directories(directory)
    ledger = directory / 'ledger.sqlite3'
    lockpath = directory / 'cycle.lock'
    ledger_fd, ledger_id = private_file(ledger)
    lock_fd = None
    db = None
    try:
        lock_fd, lock_id = private_file(lockpath)
        deadline = time.monotonic() + 45
        while True:
            try:
                fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                require(time.monotonic() < deadline, 'CYCLE_LOCK_BUSY')
                time.sleep(0.1)
        pinned(ledger, ledger_id)
        pinned(lockpath, lock_id)
        if expected is not None:
            verify_sources(expected, root)
        db = sqlite3.connect('file:/proc/self/fd/' + str(ledger_fd) + '?mode=ro', uri=True, timeout=10)
        db.execute('PRAGMA query_only=ON')
        db.execute('PRAGMA trusted_schema=OFF')
        db.execute('BEGIN')
        proof = snapshot(db)
        if before is not None:
            require(proof['journal_sha256'] == before['journal_sha256'], 'JOURNAL_CHANGED_DURING_UPDATE')
        if fresh_after is not None:
            require(fresh_off(db, fresh_after), 'FRESH_OFF_STATUS_REQUIRED')
        db.execute('COMMIT')
        if backup:
            maintenance = directory / 'maintenance'
            if not maintenance.exists():
                maintenance.mkdir(mode=0o700)
            directories(maintenance)
            info = maintenance.lstat()
            require(info.st_uid == UID and not info.st_mode & 0o077, 'BACKUP_DIRECTORY_INVALID')
            saved = Path(tempfile.mkdtemp(prefix='pnl-calendar-', dir=maintenance))
            target = saved / 'ledger.before.sqlite3'
            fd = os.open(target, os.O_RDWR | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o600)
            os.close(fd)
            out = sqlite3.connect(str(target))
            try:
                # Source has no write transaction. cycle.lock fences coordinator;
                # display-cache writers may continue and are excluded above.
                db.backup(out)
                require(snapshot(out)['journal_sha256'] == proof['journal_sha256'], 'BACKUP_NOT_VERIFIED')
            finally:
                out.close()
            proof['backup'] = str(target)
        if exchange:
            sys.path.insert(0, str(Path(root).absolute()))
            proof['exchange'] = exchange_snapshot()
        db.execute('BEGIN')
        require(snapshot(db)['journal_sha256'] == proof['journal_sha256'], 'JOURNAL_CHANGED_DURING_AUDIT')
        db.execute('COMMIT')
        pinned(ledger, ledger_id)
        pinned(lockpath, lock_id)
        proof['status'] = 'OFF_STATE_PRESERVED' if before else 'OFF_PREFLIGHT_VERIFIED'
        return proof
    finally:
        if db is not None:
            db.close()
        if lock_fd is not None:
            os.close(lock_fd)
        os.close(ledger_fd)

def source_path(root, name):
    require(isinstance(name, str) and re.fullmatch(r'[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*', name)
            and all(part not in ('.', '..') for part in name.split('/')), 'SOURCE_MAP_INVALID')
    root = Path(root).absolute()
    path = root / name
    directories(path.parent)
    return path

def file_hash(path, *, missing=False):
    if not os.path.lexists(path):
        require(missing, 'SOURCE_UNAVAILABLE')
        return None
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    try:
        info = os.fstat(fd)
        require(stat.S_ISREG(info.st_mode) and info.st_nlink == 1 and info.st_size < 2_000_000,
                'SOURCE_PATH_INVALID')
        with os.fdopen(os.dup(fd), 'rb') as stream:
            return hashlib.sha256(stream.read(2_000_001)).hexdigest()
    finally:
        os.close(fd)

def choose_sources(root):
    # Exactly the previously verified runtime or an exact idempotent rerun is
    # accepted. Never import, rewrite or expose the installed private SDK.
    matches = []
    for expected in (BASE_RUNTIME, TARGET_RUNTIME):
        try:
            verify_sources(expected, root)
            matches.append(expected)
        except (Refuse, OSError):
            pass
    require(matches, 'RUNTIME_SOURCE_MISMATCH')
    expected = matches[-1]
    for name, content in TARGET_CONTENTS.items():
        path = source_path(root, name)
        actual = file_hash(path, missing=True)
        allowed = [hashlib.sha256(content.encode()).hexdigest()]
        if name.startswith('worker/'):
            allowed.append(expected.get(name))
        else:
            declared = STATIC_BASE.get(name)
            allowed.extend(declared if isinstance(declared, list) else [declared])
            # The VPS may retain an older tracked website while all runtime
            # changes were installed in place. A clean file from its own Git
            # HEAD is accepted; uncommitted edits are still refused.
            import subprocess
            old = subprocess.run(['git', '-C', str(Path(root).absolute()), 'show', 'HEAD:' + name],
                                 stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
            if old.returncode == 0 and len(old.stdout) < 2_000_000:
                allowed.append(hashlib.sha256(old.stdout).hexdigest())
        require(actual in allowed, 'SOURCE_CHANGED')
    return expected

def backup_sources(root, backup):
    choose_sources(root)
    backup = Path(backup)
    directories(backup)
    before, after = {}, {}
    for name, content in TARGET_CONTENTS.items():
        source = source_path(root, name)
        before[name] = file_hash(source, missing=True)
        after[name] = hashlib.sha256(content.encode()).hexdigest()
        if before[name] is None:
            continue
        saved = backup / 'source-before' / name
        saved.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
        import shutil
        shutil.copy2(source, saved)
        require(file_hash(saved) == before[name], 'SOURCE_BACKUP_FAILED')
    (backup / 'files.before.json').write_text(json.dumps(before, sort_keys=True))
    (backup / 'files.after.json').write_text(json.dumps(after, sort_keys=True))
    print('SOURCE_BACKUPS_VERIFIED')

def apply_sources(root, backup):
    choose_sources(root)
    backup = Path(backup)
    before = json.loads((backup / 'files.before.json').read_text())
    require(set(before) == set(TARGET_CONTENTS), 'BACKUP_MAP_INVALID')
    for name in before:
        require(file_hash(source_path(root, name), missing=True) == before[name],
                'SOURCE_CHANGED_BEFORE_APPLY')
    for name, content in TARGET_CONTENTS.items():
        path = source_path(root, name)
        info = path.lstat() if before[name] is not None else None
        descriptor, temporary = tempfile.mkstemp(prefix='.pnl-source-', dir=path.parent)
        try:
            with os.fdopen(descriptor, 'wb') as out:
                os.fchmod(out.fileno(), stat.S_IMODE(info.st_mode) if info else 0o644)
                if info:
                    os.fchown(out.fileno(), info.st_uid, info.st_gid)
                out.write(content.encode()); out.flush(); os.fsync(out.fileno())
            require(file_hash(path, missing=True) == before[name], 'SOURCE_CHANGED_DURING_APPLY')
            os.replace(temporary, path)
        finally:
            if os.path.lexists(temporary): os.unlink(temporary)
    verify_sources(TARGET_RUNTIME, root)
    for name, content in TARGET_CONTENTS.items():
        require(file_hash(source_path(root, name)) == hashlib.sha256(content.encode()).hexdigest(),
                'SOURCE_TARGET_MISMATCH')
        if name.endswith('.py'): compile(content, name, 'exec')
    print('SOURCE_COMPILE_VERIFIED')

def restore_sources(root, backup):
    backup = Path(backup)
    before = json.loads((backup / 'files.before.json').read_text())
    after = json.loads((backup / 'files.after.json').read_text())
    require(set(before) == set(after) == set(TARGET_CONTENTS), 'BACKUP_MAP_INVALID')
    # Validate the entire set before touching any file. Refuse concurrent edits.
    for name in before:
        actual = file_hash(source_path(root, name), missing=True)
        require(actual in (before[name], after[name]), 'SOURCE_CHANGED_DURING_UPDATE')
        if before[name] is not None:
            require(file_hash(backup / 'source-before' / name) == before[name], 'SOURCE_BACKUP_CHANGED')
    import shutil
    for name in before:
        path = source_path(root, name)
        if before[name] is not None: shutil.copy2(backup / 'source-before' / name, path)
        elif os.path.lexists(path): path.unlink()
    print('SOURCE_RESTORED')

def validate_cache(path):
    path = Path(path)
    directories(path.parent)
    info = path.parent.lstat()
    require(info.st_uid == UID and not info.st_mode & 0o077, 'HISTORY_DIRECTORY_NOT_PRIVATE')
    if not os.path.lexists(path): return False
    descriptor, identity = private_file(path)
    try: pinned(path, identity)
    finally: os.close(descriptor)
    return True

def calendar_postflight(root='/app', data_dir='/data'):
    require(os.geteuid() == UID, 'WORKER_UID_REQUIRED')
    sys.path.insert(0, str(Path(root).absolute()))
    from worker.binance_private import BinanceReadOnly
    from worker.pnl_calendar import collect_calendar
    directory = Path(data_dir).absolute() / 'trading'
    directories(directory)
    client = BinanceReadOnly()
    deadline = time.monotonic() + 45
    while True:
        calendar = collect_calendar(client, directory, max_requests=4, budget_seconds=15)
        if 'PNL_REFRESH_BUSY' not in calendar.get('incomplete_reasons', []): break
        require(time.monotonic() < deadline, 'CALENDAR_REFRESH_BUSY')
        time.sleep(1)
    require(isinstance(calendar, dict), 'CALENDAR_CONTRACT_INVALID')
    calendar_contract(calendar)
    calendar_collection_check(calendar)
    require(validate_cache(directory / 'pnl-history-v1.json'), 'HISTORY_CACHE_UNAVAILABLE')
    validate_cache(directory / 'pnl-history.lock')
    # Verify the HTTP response contract used by the website, with the same
    # private read token as health.py. The token and response body are not logged.
    from urllib.request import Request, build_opener, ProxyHandler
    from worker.http_client import NoRedirect, unique
    token = Path('/run/office/read_token').read_text().strip()
    require(bool(token), 'READ_TOKEN_UNAVAILABLE')
    request = Request('http://127.0.0.1:8787/office/status', method='GET',
                      headers={'Authorization': 'Bearer ' + token, 'Accept': 'application/json'})
    with build_opener(ProxyHandler({}), NoRedirect()).open(request, timeout=15) as response:
        require(response.code == 200, 'OFFICE_HTTP_CONTRACT_INVALID')
        raw = response.read(2_000_001)
        require(len(raw) <= 2_000_000, 'OFFICE_HTTP_RESPONSE_LIMIT')
        office = json.loads(raw, object_pairs_hook=unique)
    require(isinstance(office, dict) and isinstance(office.get('pnl_calendar'), dict),
            'OFFICE_HTTP_CONTRACT_INVALID')
    calendar_contract(office['pnl_calendar'])
    calendar_collection_check(office['pnl_calendar'])
    require(isinstance(office.get('robot'), dict) and office['robot'].get('robot_on') is False,
            'ROBOT_OFF_REQUIRED')
    summary = calendar_summary(calendar)
    summary['office_http_get_verified'] = True
    summary['office_calendar_status'] = office['pnl_calendar']['status']
    return summary

def calendar_contract(calendar):
    require(calendar.get('kind') == 'CLOSED_POSITIONS_FROM_FILLS'
            and calendar.get('timezone') == 'Asia/Jakarta'
            and calendar.get('start_date') == '2026-10-01'
            and calendar.get('status') in ('COMPLETE', 'PARTIAL', 'UNAVAILABLE'), 'CALENDAR_CONTRACT_INVALID')
    reasons = calendar.get('incomplete_reasons')
    require(isinstance(reasons, list) and len(reasons) <= 100 and
            all(isinstance(value, str) and re.fullmatch(r'[A-Z_]{1,100}', value) for value in reasons),
            'CALENDAR_CONTRACT_INVALID')
    require(type(calendar.get('complete')) is bool and isinstance(calendar.get('days'), list)
            and len(calendar['days']) <= 36_600, 'CALENDAR_CONTRACT_INVALID')
    dates = set()
    for row in calendar['days']:
        require(isinstance(row, dict) and isinstance(row.get('date'), str)
                and re.fullmatch(r'\d{4}-\d{2}-\d{2}', row['date'])
                and row['date'] >= '2026-10-01' and row['date'] not in dates,
                'CALENDAR_CONTRACT_INVALID')
        require(datetime.fromisoformat(row['date']).date().isoformat() == row['date'],
                'CALENDAR_CONTRACT_INVALID')
        dates.add(row['date'])
        require(type(row.get('closed_positions')) is int and 0 <= row['closed_positions'] <= 100_000
                and type(row.get('complete')) is bool, 'CALENDAR_CONTRACT_INVALID')
        for key in ('pnl_usdt', 'known_pnl_usdt'):
            value = row.get(key)
            require(value is None or isinstance(value, str) and len(value) <= 128
                    and re.fullmatch(r'-?\d+(?:\.\d+)?', value), 'CALENDAR_CONTRACT_INVALID')

def calendar_collection_check(calendar):
    from worker.binance_private import CODES
    fatal = set(CODES) | {'PNL_CACHE_IDENTITY_UNAVAILABLE', 'PNL_CACHE_INVALID',
        'PNL_CACHE_NOT_PRIVATE', 'PNL_CACHE_LIMIT', 'PNL_VALUE_LIMIT',
        'PNL_HISTORY_INVALID', 'PNL_HISTORY_UNAVAILABLE', 'PNL_HISTORY_PAGINATION_STALLED',
        'PNL_POSITION_SNAPSHOT_INVALID'}
    # A valid response shape and an old cache do not prove that today's
    # authenticated Futures history could be read. Loading/limited-scope facts
    # remain usable, while transport/authentication and structural failures stop
    # verification and leave source/image rollback armed.
    require(not fatal.intersection(calendar['incomplete_reasons']), 'CALENDAR_COLLECTION_FAILED')

def calendar_summary(calendar):
    return dict(status='CALENDAR_READ_VERIFIED', kind=calendar['kind'],
                collection_status=calendar['status'], start_date=calendar['start_date'],
                timezone=calendar['timezone'], complete=calendar.get('complete') is True,
                days=[{key: row[key] for key in ('date', 'pnl_usdt', 'known_pnl_usdt', 'closed_positions', 'complete')}
                      for row in calendar['days'] if row['closed_positions']][:366],
                incomplete_reasons=calendar.get('incomplete_reasons', []))

def offline_image(root='/app'):
    verify_sources(TARGET_RUNTIME, root)
    for name in TARGET_RUNTIME: compile((Path(root) / name).read_bytes(), name, 'exec')
    sys.path.insert(0, str(Path(root).absolute()))
    from worker.pnl_calendar import collect_calendar, unavailable
    require(callable(collect_calendar), 'CALENDAR_COLLECTOR_UNAVAILABLE')
    import worker.api_service, worker.robot_store
    calendar_contract(unavailable('HISTORY_LOADING', 1791378000000))
    calendar_contract(worker.robot_store.unavailable_office()['pnl_calendar'])
    require(BASE_RUNTIME['worker/order_gateway.py'] == TARGET_RUNTIME['worker/order_gateway.py'],
            'PRIVATE_GATEWAY_CHANGED')
    print('OFFLINE_IMAGE_VERIFIED')

def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument('--mode', required=True, choices=('host-check', 'backup-sources', 'apply-sources',
        'restore-sources', 'audit', 'offline-image', 'calendar'))
    parser.add_argument('--root', default='.')
    parser.add_argument('--backup-root')
    parser.add_argument('--data-dir', default='/data')
    parser.add_argument('--source-hashes-json')
    parser.add_argument('--before-json')
    parser.add_argument('--backup', action='store_true')
    parser.add_argument('--exchange', action='store_true')
    parser.add_argument('--fresh-after', type=float)
    args = parser.parse_args(argv)
    try:
        if args.mode == 'host-check':
            result = choose_sources(args.root)
            print(json.dumps(result, sort_keys=True))
        elif args.mode == 'backup-sources': backup_sources(args.root, args.backup_root)
        elif args.mode == 'apply-sources': apply_sources(args.root, args.backup_root)
        elif args.mode == 'restore-sources': restore_sources(args.root, args.backup_root)
        elif args.mode == 'offline-image': offline_image(args.root)
        elif args.mode == 'calendar': print(json.dumps(calendar_postflight(args.root, args.data_dir), sort_keys=True))
        elif args.mode == 'audit':
            result = inspect(args.data_dir, expected=json.loads(args.source_hashes_json), root=args.root,
                before=json.loads(args.before_json) if args.before_json else None,
                backup=args.backup, exchange=args.exchange, fresh_after=args.fresh_after)
            if args.before_json and args.exchange:
                result['exchange_changed_during_update'] = (
                    result.get('exchange') != json.loads(args.before_json).get('exchange'))
            print(json.dumps(result, sort_keys=True))
        return 0
    except Exception as error:
        read_codes = {'BINANCE_NOT_CONFIGURED', 'BINANCE_AUTH_FAILED', 'BINANCE_IP_RESTRICTED',
            'BINANCE_PERMISSION_DENIED', 'BINANCE_CLOCK_ERROR', 'BINANCE_ACCOUNT_UNAVAILABLE',
            'BINANCE_ENDPOINT_DENIED'}
        reason = str(error) if isinstance(error, Refuse) or str(error) in read_codes else type(error).__name__
        print(json.dumps(dict(status='PNL_CALENDAR_UPDATE_REFUSED', reason=reason), sort_keys=True))
        return 1

if __name__ == '__main__':
    raise SystemExit(main())
